  "{n} more losses in a row and you'll drop to {tier}": { one: "{n} more loss in a row and you'll drop to {tier}", other: "{n} more losses in a row and you'll drop to {tier}" },
  "{n} wins left to promote": { one: "{n} win left to promote", other: "{n} wins left to promote" },
  "You need {n} more wins in a row to rank up.": { one: "You need {n} more win in a row to rank up.", other: "You need {n} more wins in a row to rank up." },
  "{n} players online": { one: "{n} player online", other: "{n} players online" },
  "{hero} mulligans {n} cards.": { one: "{hero} mulligans {n} card.", other: "{hero} mulligans {n} cards." },
  "Defeat {hero} {n} times.": { one: "Defeat {hero} {n} time.", other: "Defeat {hero} {n} times." },
