// The language starts as the browser's language (if we have it), otherwise English.
const DEFAULT_DISPLAY = { mode: "deluxe", lang: "en" };
function loadDisplaySettings() {
  let p = {};
  try { p = JSON.parse(window.localStorage.getItem(DISPLAY_STORAGE_KEY) || "{}") || {}; } catch (e) { p = {}; }
  return {
    mode: DISPLAY_MODES.some((m) => m.id === p.mode) ? p.mode : DEFAULT_DISPLAY.mode,
    lang: LANGS.some((l) => l.id === p.lang) ? p.lang : detectLang(),
  };
}
