      <g fill="#ffffff">{[[2, 0], [6, 0.8], [9, 0.3], [12, 1.4], [4, 1.8]].map(([x, d], i) => <rect key={i} className="dx-pix-snow" x={x} y="-1" width="1" height="1" style={{ animationDelay: `${d}s` }} />)}</g>
