        {title && <div style={{ fontWeight: 800, fontSize: pixel ? 14 : 14, color: KW_COLORS[info.id][dark ? 1 : 0], marginBottom: 3, textTransform: themed ? "uppercase" : "none", letterSpacing: themed && !pixel ? "0.06em" : 0 }}>{title}</div>}
