        <div style={{ fontWeight: 700, fontSize: 13 }}>[{c.cost}] {cardNameL(c)}</div>
        {c.type !== "spell" && <div style={{ fontSize: 11, marginTop: 2 }}>{tr("ATK")} {c.atk} · {tr("HP")} {c.hp}</div>}
        {cardTextL(c) && <div style={{ fontSize: 11, marginTop: 4, color: "#333" }}>{cardTextL(c)}</div>}
