        {(() => { const t = tr("STANDARD SET"); return <div style={{ position: "absolute", left: 6, right: 6, top: 232, textAlign: "center", fontFamily: DX_DISPLAY_FONT, fontWeight: 700, fontSize: t.length > 14 ? 9.5 : 11.5, letterSpacing: t.length > 14 ? "0.1em" : "0.3em", color: "#3a4653", whiteSpace: "nowrap" }}>{t}</div>; })()}
