      <div style={{ position: "absolute", left: 0, top: 0, width: DX_CARD_W, height: DX_CARD_H, transformOrigin: "0 0", transform: `scale(${s}) perspective(900px) rotateX(var(--dx-rx,0deg)) rotateY(var(--dx-ry,0deg))`, transition: "transform 0.12s ease-out" }}>
        <div className="dx-cb">
          <div className="dx-cb-tex" />
          <div style={{ position: "absolute", inset: 0, background: "radial-gradient(ellipse at 50% 46%, rgba(120,170,230,0.22), rgba(0,0,0,0) 60%)" }} />
          <div className="dx-cb-frame" />
          {[[16, 16], [224, 16], [16, 320], [224, 320]].map(([x, y], i) => <div key={i} className="dx-cb-corner" style={{ left: x - 6, top: y - 6 }} />)}
          <div style={{ position: "absolute", left: 22, right: 22, top: 38, display: "flex", justifyContent: "center", filter: "drop-shadow(0 4px 6px rgba(0,0,0,0.7))" }}>
            <BrandLogo variant={sk.pixel ? "pixel" : "color"} width={186} />
          </div>
          <div style={{ position: "absolute", left: "50%", top: 122, width: 92, height: 92, marginLeft: -46, borderRadius: sk.pixel ? 0 : "50%", background: "radial-gradient(circle, #233142 0%, #0a0e13 72%)", boxShadow: "0 0 0 3px rgba(225,233,241,0.85), 0 0 0 6px #3c444d, 0 0 0 7px rgba(225,233,241,0.4), 0 10px 22px rgba(0,0,0,0.6), 0 0 30px rgba(140,200,255,0.35)" }}>
            <div style={{ position: "absolute", left: 22, top: 22, width: 48, height: 48, transform: "rotate(45deg)", background: "linear-gradient(135deg,#ffffff 0%,#bfe6ff 30%,#7fb7ff 50%,#e7c9ff 70%,#ffffff 100%)", boxShadow: "0 0 20px rgba(170,220,255,1), inset 0 0 10px rgba(255,255,255,0.9)" }}>
              <div style={{ position: "absolute", inset: 0, background: "linear-gradient(90deg, rgba(255,255,255,0) 48%, rgba(255,255,255,0.7) 50%, rgba(255,255,255,0) 52%), linear-gradient(0deg, rgba(255,255,255,0) 48%, rgba(255,255,255,0.7) 50%, rgba(255,255,255,0) 52%)" }} />
            </div>
          </div>
          <div className="dx-cb-title" style={{ position: "absolute", left: 10, right: 10, top: 238, fontSize: t1.length > 8 ? 19 : 24, letterSpacing: t1.length > 8 ? "0.08em" : "0.2em" }}>{t1}</div>
          <div className="dx-cb-sub" style={{ position: "absolute", left: 10, right: 10, top: 274, fontSize: t2.length > 14 ? 9.5 : 11.5, letterSpacing: t2.length > 14 ? "0.12em" : "0.32em" }}>{t2}</div>
          {CB_TWINKLES.map(([x, y, d], i) => <div key={i} className="dx-cb-tw" style={{ left: x, top: y, animationDelay: d + "s" }} />)}
          <div className="dx-cb-sheen" />
          <div className="dx-cb-glare" />
        </div>
      </div>
