/* sparks + swoosh (rare and better) and fireworks (unique) when a card turns */
const FX_COLORS = { rare: ["#7cc8ff", "#3f9dff"], epic: ["#8fd0ff", "#c48bff"], unique: ["#9ad8ff", "#ffd25a"] };
const FW_COLORS = ["#ff5a5a", "#ffd25a", "#7cff8a", "#7cc8ff", "#d68bff", "#ff9a3a"];
function RevealFx({ rarity, w, h }) {
  const [c1, c2] = FX_COLORS[rarity] || FX_COLORS.rare;
  const n = rarity === "rare" ? 16 : 24;
  const rx = w * 0.62, ry = h * 0.58;
  const sparks = Array.from({ length: n }, (_, i) => {
    const a = (360 / n) * i + (i % 3) * 5;
    const rad = (a * Math.PI) / 180;
    const r0 = Math.hypot(Math.sin(rad) * w * 0.48, Math.cos(rad) * h * 0.48);
    return { a, r0, r1: r0 + 40 + (i % 4) * 16, c: i % 2 ? c1 : c2, d: (i % 5) * 0.03 };
  });
  const bursts = rarity === "unique" ? [[-0.75, -0.55, 0.15], [0.8, -0.45, 0.45], [-0.85, 0.35, 0.75], [0.75, 0.5, 1.0], [0, -0.85, 1.3], [-0.2, 0.9, 1.55], [0.55, -0.9, 1.85]] : [];
  return (
    <div className="dx-fx">
      <div className="fl" style={{ left: -w * 0.6, top: -h * 0.6, width: w * 1.2, height: h * 1.2, background: `radial-gradient(ellipse, rgba(255,255,255,0.9), ${c1}88 35%, rgba(0,0,0,0) 70%)` }} />
      <svg style={{ left: -rx, top: -ry, width: rx * 2, height: ry * 2 }} viewBox={`${-rx} ${-ry} ${rx * 2} ${ry * 2}`}>
        <ellipse className="sw" cx="0" cy="0" rx={rx} ry={ry} pathLength="100" stroke={c1} strokeWidth="7" style={{ filter: `drop-shadow(0 0 6px ${c1}) drop-shadow(0 0 14px ${c1})` }} />
        <ellipse className="sw" cx="0" cy="0" rx={rx * 0.92} ry={ry * 0.92} pathLength="100" stroke="#ffffff" strokeWidth="3" transform="rotate(180)" style={{ animationDelay: "0.08s", filter: `drop-shadow(0 0 8px ${c2})` }} />
      </svg>
      {sparks.map((p, i) => <i key={i} className="sp" style={{ "--a": p.a + "deg", "--r0": p.r0 + "px", "--r1": p.r1 + "px", "--c": p.c, animationDelay: p.d + "s" }} />)}
      {bursts.map(([bx, by, d], j) => (
        <div key={"b" + j} className="dx-fw" style={{ left: bx * w, top: by * h, animationDelay: d + "s" }}>
          <i className="c" style={{ "--c": FW_COLORS[j % FW_COLORS.length], animationDelay: d + "s" }} />
          {Array.from({ length: 24 }, (_, k) => <i key={k} className="p" style={{ "--a": k * 15 + "deg", "--d": 70 + (k % 3) * 22 + "px", "--c": FW_COLORS[(j + (k % 2) * 2) % FW_COLORS.length], animationDelay: d + "s" }} />)}
        </div>
      ))}
    </div>
  );
}

/* the pack cracks, then breaks into shards flying out from its middle */
const SHARD_RIM = [[0, 0], [30, 0], [62, 0], [100, 0], [100, 28], [100, 60], [100, 100], [70, 100], [38, 100], [0, 100], [0, 66], [0, 34]];
const SHARD_C = [52, 47];
function PackShatter({ scale }) {
  return (
    <div style={{ position: "relative", width: 200 * scale, height: 290 * scale }}>
      {SHARD_RIM.map((p, i) => {
        const q = SHARD_RIM[(i + 1) % SHARD_RIM.length];
        const cx = (p[0] + q[0] + SHARD_C[0]) / 3 - SHARD_C[0], cy = (p[1] + q[1] + SHARD_C[1]) / 3 - SHARD_C[1];
        const len = Math.hypot(cx, cy) || 1;
        const dist = 380 + (i % 3) * 120;
        return (
          <div key={i} className="dx-shard" style={{ clipPath: `polygon(${SHARD_C[0]}% ${SHARD_C[1]}%, ${p[0]}% ${p[1]}%, ${q[0]}% ${q[1]}%)`, "--tx": (cx / len) * dist + "px", "--ty": (cy / len) * dist + "px", "--r": (i % 2 ? 1 : -1) * (120 + i * 25) + "deg" }}>
            <DiamondPackArt scale={scale} />
          </div>
        );
      })}
    </div>
  );
}
function PackCracks() {
  return (
    <svg className="dx-crack" viewBox="0 0 200 290" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", pointerEvents: "none", overflow: "visible", filter: "drop-shadow(0 0 6px #ffb84a)" }}>
      {["M104 136 L80 98 L86 70 L60 30", "M104 136 L140 110 L150 80 L178 60", "M104 136 L128 170 L120 210 L150 262", "M104 136 L70 160 L52 200 L22 214", "M104 136 L98 90 L112 52", "M104 136 L150 150 L188 170"].map((d, i) => (
        <g key={i}>
          <path d={d} pathLength="100" fill="none" stroke="#120d06" strokeWidth={i < 4 ? 6 : 4} strokeLinejoin="round" style={{ animationDelay: i * 0.05 + "s" }} />
          <path d={d} pathLength="100" fill="none" stroke="#fff6c8" strokeWidth={i < 4 ? 2.2 : 1.6} strokeLinejoin="round" style={{ animationDelay: i * 0.05 + "s" }} />
        </g>
      ))}
    </svg>
  );
}
function PackBlast() {
  return (
    <div className="dx-blast">
      <img className="img" src={EXPLOSION_SRC} alt="" draggable={false} />
      <img className="img2" src={EXPLOSION_SRC} alt="" draggable={false} />
      <i className="core" />
      <i className="wave" />
      <i className="wave w2" />
      {Array.from({ length: 36 }, (_, i) => <i key={"e" + i} className="em" style={{ "--a": i * 10 + (i % 4) * 3 + "deg", "--d": 260 + ((i * 37) % 5) * 80 + "px", animationDelay: (i % 6) * 0.025 + "s", height: 16 + (i % 3) * 12 }} />)}
      {Array.from({ length: 16 }, (_, i) => <i key={"r" + i} className="rock" style={{ "--a": i * 22.5 + 9 + "deg", "--d": 300 + (i % 4) * 110 + "px", "--s": (i % 2 ? 1 : -1) * 540 + "deg", animationDelay: (i % 4) * 0.04 + "s", transform: `scale(${0.6 + (i % 3) * 0.45})` }} />)}
    </div>
  );
}

/* "you have unopened packs" count badge (like an unread-messages dot) */
const PKB_CSS = `
.dx-pkb { position: absolute; top: -7px; right: -13px; z-index: 30; pointer-events: none; min-width: 16px; height: 16px; padding: 0 4px; box-sizing: border-box; border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center; font: 800 10px/1 system-ui, -apple-system, "Segoe UI", sans-serif; letter-spacing: 0; text-transform: none; color: #fff; background: #ff7a00; box-shadow: 0 0 0 2px rgba(0,0,0,0.55); }
.dx-pkb.np { box-shadow: 0 0 0 2px #fff; }
.dx-pk-dot { position: static; margin-left: 8px; vertical-align: middle; }
`;
function PacksBubble({ n, inline }) {
  const sk = useSkinS();
  if (!n || n <= 0) return null;
  return (
    <>
      <style>{PKB_CSS}</style>
      <span className={"dx-pkb" + (sk.themed ? "" : " np") + (inline ? " dx-pk-dot" : "")} aria-label={n === 1 ? tr("1 pack to open!") : tr("{n} packs to open!", { n })}>{n > 99 ? "99+" : n}</span>
    </>
  );
}

/* Normal / Diamond switch for the deck builders (only one version is drawn at a time - lighter on phones) */
function DeckViewToggle({ view, setView, profile }) {
  const sk = useSkinS();
  const has = profile && profile.diamonds && Object.values(profile.diamonds).some((n) => n > 0);
  const opts = [["normal", tr("Normal")], ["diamond", "◆ " + tr("Diamond")]];
  return (
    <div style={{ display: "inline-flex", marginTop: 10, marginBottom: 6, border: sk.themed ? "1px solid rgba(255,255,255,0.3)" : "2px solid #000", borderRadius: sk.pixel ? 0 : sk.themed ? 999 : 6, overflow: "hidden" }}>
      {opts.map(([v, l]) => (
        <button key={v} type="button" onClick={() => setView(v)} disabled={v === "diamond" && !has}
          style={{ border: "none", padding: sk.themed ? "7px 18px" : "5px 14px", cursor: v === "diamond" && !has ? "default" : "pointer", font: "inherit", fontSize: 13, fontWeight: 800, letterSpacing: "0.05em", opacity: v === "diamond" && !has ? 0.45 : 1,
            background: view === v ? (sk.themed ? (v === "diamond" ? "linear-gradient(180deg,#ffffff,#bfe3ff)" : "#e0a94a") : "#000") : "transparent", color: view === v ? (sk.themed ? "#14100a" : "#fff") : "inherit" }}>{l}</button>
      ))}
    </div>
  );
}

/* a small crystal crown on a Diamond minion on the table, so both players can tell */
const MIN_CROWN = DIA_CROWN.slice(0, 7).map(([x, y]) => [x * 150 / 240, y * 0.62]);
function DiamondMinionCrown({ rarity, pixel }) {
  const t = DIA_TINT[rarity] || DIA_TINT.common;
  const pts = [[0, 14], ...MIN_CROWN, [150, 14]].map((p) => p.join(",")).join(" ");
  const id = "mcg-" + rarity;
  return (
    <svg viewBox="0 -26 150 40" width="150" height="40" style={{ position: "absolute", left: 0, top: -24, overflow: "visible", pointerEvents: "none", filter: pixel ? undefined : `drop-shadow(0 0 6px ${t.c})` }} shapeRendering={pixel ? "crispEdges" : undefined}>
      <defs><linearGradient id={id} x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#ffffff" /><stop offset="0.45" stopColor={t.c} /><stop offset="0.7" stopColor="#ffffff" /><stop offset="1" stopColor={t.c} /></linearGradient></defs>
      <polygon points={pts} fill={pixel ? t.c : `url(#${id})`} stroke={pixel ? "#0a0a06" : rarity === "common" ? "#8aa2b8" : "rgba(255,255,255,0.9)"} strokeWidth={pixel ? 3 : 1.8} strokeLinejoin="round" />
      {!pixel && MIN_CROWN.filter((_, i) => i % 2 === 1).map(([x, y], i) => <line key={i} x1={x} y1={y} x2={x} y2={6} stroke="rgba(255,255,255,0.75)" strokeWidth="1" />)}
      <circle cx={75} cy={-14} r={3.2} fill="#fff" style={{ filter: pixel ? undefined : "drop-shadow(0 0 4px #fff)" }} />
    </svg>
  );
}

/* "Are you sure?" before anything is bought: askConfirm(text) -> Promise<boolean> */
function askConfirm(text) {
  return new Promise((resolve) => shopSet({ ask: { text, resolve } }));
}
function ConfirmHost() {
  const [ask, setAsk] = useState(SHOP.ask || null);
  useEffect(() => { const f = (x) => setAsk(x.ask || null); SHOP.ls.add(f); return () => { SHOP.ls.delete(f); }; }, []);
  const sk = useSkinS();
  if (!ask) return null;
  const done = (v) => { shopSet({ ask: null }); ask.resolve(v); };
  const panel = sk.themed
    ? { background: "linear-gradient(180deg, rgba(34,29,24,0.98), rgba(14,12,10,0.99))", color: "#efe7d8", border: "1px solid rgba(255,200,110,0.45)", borderRadius: sk.pixel ? 0 : 14, boxShadow: "0 20px 50px rgba(0,0,0,0.6)" }
    : { background: "#fff", color: "#111", border: "3px solid #000", borderRadius: 10 };
  return createPortal(
    <div data-tut-popup="1" className={sk.themed ? dxRootClass(sk.mode) : undefined} onClick={() => done(false)}
      style={{ position: "fixed", inset: 0, zIndex: 700, background: "rgba(0,0,0,0.6)", display: "flex", alignItems: "center", justifyContent: "center", padding: 16, fontFamily: sk.font }}>
      <div onClick={(e) => e.stopPropagation()} role="dialog" aria-modal="true" style={{ ...panel, width: "min(380px, 100%)", padding: 20, textAlign: "center", boxSizing: "border-box" }}>
        <div style={{ fontSize: 16, fontWeight: 800, lineHeight: 1.4 }}>{ask.text}</div>
        <div style={{ display: "flex", gap: 10, marginTop: 18, justifyContent: "center", flexWrap: "wrap" }}>
          <button type="button" autoFocus className={sk.themed ? "fx-btn fx-btn-primary" : undefined} style={sk.themed ? { minWidth: 120 } : npBtn(true, { minWidth: 110 })} onClick={() => done(true)}>{tr("Buy")}</button>
          <button type="button" className={sk.themed ? "fx-btn" : undefined} style={sk.themed ? { minWidth: 120 } : npBtn(false, { minWidth: 110 })} onClick={() => done(false)}>{tr("Cancel")}</button>
        </div>
      </div>
    </div>,
    document.body
  );
}
/* Game logo (art/logo, made by tools/mklogo.py from the logo artwork):
   colour = sign-in screen, white = Full Graphics header, pixel = Pixel Art, black = notepad styles. */
const LOGO_SRC = {
  color: "data:image/webp;base64,",
  white: "data:image/webp;base64,",
  black: "data:image/webp;base64,",
  pixel: "data:image/png;base64,",
};
function BrandLogo({ variant = "white", height, width, style, className }) {
  return (
    <img src={LOGO_SRC[variant]} alt="Atomic Bunch" className={className} draggable={false}
      style={{ display: "block", height: height || "auto", width: width || "auto", maxWidth: "100%", imageRendering: variant === "pixel" ? "pixelated" : undefined, userSelect: "none", ...style }} />
  );
}
