function MiniCard({ cardId, onClick, disabled, small, allowDetail, costText, diamond }) {
  const c = findCard(cardId);
  const r = RARITY_STYLE[c.rarity];
  const badgeReserve = small ? 20 : 22;
  const [showDetail, setShowDetail] = useState(false);
  const pressTimer = useRef(null);
  const longPressFired = useRef(false);
  const displayMode = useDisplay().mode;
  const noArt = displayMode === "noart";
  const isDia = diamond !== undefined ? !!diamond : (SHOP.diamonds[cardId] > 0);
  const diaT = isDia ? (DIA_TINT[c.rarity] || DIA_TINT.common) : null;

  const startPress = () => {
    if (!allowDetail) return;
    longPressFired.current = false;
    pressTimer.current = setTimeout(() => {
      longPressFired.current = true;
      setShowDetail(true);
    }, 550);
  };
  const cancelPress = () => {
    if (pressTimer.current) { clearTimeout(pressTimer.current); pressTimer.current = null; }
  };
  const handleClick = (e) => {
    if (longPressFired.current) {
      longPressFired.current = false;
      e.stopPropagation();
      return;
    }
    if (!disabled && onClick) onClick();
  };
  const handleContextMenu = (e) => {
    if (!allowDetail) return;
    e.preventDefault();
    e.stopPropagation();
    setShowDetail(true);
  };

  // Full Graphics / Pixel Art: same clicks and long-press as below, drawn as a full card face.
  if (isThemedMode(displayMode)) {
    return (
      <>
        <div
          className={dxRootClass(displayMode)}
          onClick={handleClick}
          onContextMenu={handleContextMenu}
          onMouseDown={startPress}
          onMouseUp={cancelPress}
          onMouseLeave={cancelPress}
          onTouchStart={startPress}
          onTouchEnd={cancelPress}
          onTouchMove={cancelPress}
          style={{ cursor: disabled ? "default" : "pointer", padding: 7 }}
          title={cardTextL(c) || cardNameL(c)}
        >
          <DeluxeCard card={c} scale={small ? 0.6 : 0.72} dim={disabled} tilt diamond={isDia} />
        </div>
        {showDetail && <CardDetailModal card={c} diamond={isDia} onClose={() => setShowDetail(false)} />}
      </>
    );
  }

  return (
    <>
    <div
      onClick={handleClick}
      onContextMenu={handleContextMenu}
      onMouseDown={startPress}
      onMouseUp={cancelPress}
      onMouseLeave={cancelPress}
      onTouchStart={startPress}
      onTouchEnd={cancelPress}
      onTouchMove={cancelPress}
      style={{
        width: small ? 92 : 112, minWidth: small ? 92 : 112, height: small ? 132 : 160,
        border: `2px ${c.type === "spell" ? "dashed" : "solid"} ${diaT ? diaT.c === "#eef6ff" ? "#9fb6cc" : diaT.c : r.border}`, borderRadius: 6,
        background: diaT ? `linear-gradient(135deg, #ffffff 0%, rgba(${diaT.rgb},0.45) 28%, #ffffff 48%, rgba(${diaT.rgb},0.55) 72%, #ffffff 100%)` : r.bg,
        ...(diaT ? { boxShadow: `0 0 0 1px #fff inset, 0 0 9px rgba(${diaT.rgb},0.95)` } : {}),
        ...(diaT && c.rarity === "unique" ? { clipPath: "polygon(10px 0, calc(100% - 10px) 0, 100% 10px, 100% calc(100% - 10px), calc(100% - 10px) 100%, 10px 100%, 0 calc(100% - 10px), 0 10px)" } : {}),
        display: "flex", flexDirection: "column", alignItems: "center", padding: 4,
        cursor: disabled ? "default" : "pointer", opacity: disabled ? 0.55 : 1,
        boxShadow: "1px 1px 0 rgba(0,0,0,0.15)", position: "relative", fontFamily: FONT,
        userSelect: "none", boxSizing: "border-box",
      }}
      title={cardTextL(c) || cardNameL(c)}
    >
      <div style={{ position: "relative", width: "100%", flexShrink: 0 }}>
        <div style={{ position: "absolute", top: 0, left: 0, fontSize: small ? 10 : 11, fontWeight: 700, border: "1px solid #000", borderRadius: 3, minWidth: 14, textAlign: "center", lineHeight: "14px", background: "#fff", zIndex: 1, padding: costText ? "0 2px" : 0 }}>{costText || c.cost}</div>
        <div style={{ paddingLeft: badgeReserve, paddingRight: badgeReserve }}>
          <WrapFitText text={cardNameL(c)} width="100%" height={small ? 22 : 24} maxFontSize={small ? 9 : 10} minFontSize={5.5} duration={7} />
        </div>
      </div>
      {diaT && <div style={{ position: "absolute", top: 1, right: 3, fontSize: small ? 10 : 12, color: diaT.c === "#eef6ff" ? "#6f8fb0" : diaT.c, textShadow: "0 0 3px #fff", zIndex: 2 }}>◆</div>}
      <div style={{ marginTop: 1, flexShrink: 0 }}><CardArt card={c} size={small ? 36 : 48} /></div>
      {c.text && <div style={{ marginTop: 1, width: "100%", flexShrink: 0 }}><AutoScrollText text={richCardText(c)} height={(small ? 46 : 56) + (noArt ? (small ? 36 : 48) : 0)} fontSize={noArt ? (small ? 9 : 10) : (small ? 8 : 8.5)} duration={10} bold /></div>}
      <div style={{ marginTop: "auto", flexShrink: 0, display: "flex", justifyContent: "space-between", width: "100%", height: small ? 16 : 18 }}>
        {c.type === "spell" ? (
          <span style={{ margin: "auto", fontSize: small ? 8 : 9, fontWeight: 700, letterSpacing: 1 }}>{tr("ITEM")}</span>
        ) : (
          <>
            <div style={{ textAlign: "center", lineHeight: 1 }}>
              <div style={{ fontSize: small ? 5.5 : 6, color: "#555" }}>{tr("ATK")}</div>
              <div style={{ fontSize: small ? 10 : 11, fontWeight: 700 }}>{c.atk}</div>
            </div>
            <div style={{ textAlign: "center", lineHeight: 1 }}>
              <div style={{ fontSize: small ? 5.5 : 6, color: "#555" }}>{tr("HP")}</div>
              <div style={{ fontSize: small ? 10 : 11, fontWeight: 700 }}>{c.hp}</div>
            </div>
          </>
        )}
      </div>
    </div>
    {showDetail && <CardDetailModal card={c} diamond={isDia} onClose={() => setShowDetail(false)} />}
    </>
  );
}

function cardLikeForMinion(m) {
  if (m.cardId) return findCard(m.cardId);
  return { id: m.name, name: m.name, cost: null, atk: m.atk, hp: m.hp, rarity: "common", type: "minion", text: m.keywords && m.keywords.length ? m.keywords.join(", ") : "", keywords: m.keywords || [] };
}

function CardDetailModal({ card, onClose, diamond }) {
  const r = RARITY_STYLE[card.rarity];
  const displayMode = useDisplay().mode;
  if (isThemedMode(displayMode)) return <DeluxeCardDetail card={card} diamond={diamond} onClose={onClose} />;
  return (
    <div data-tut-popup="1" style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 100 }} onClick={onClose}>
      <div
        data-kwtap="1"
        onClick={(e) => e.stopPropagation()}
        style={{
          width: 302, border: `3px ${card.type === "spell" ? "dashed" : "solid"} ${r.border}`, borderRadius: 10,
          background: r.bg, padding: 16, fontFamily: FONT, boxShadow: "2px 2px 0 rgba(0,0,0,0.25)", textAlign: "center",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8, marginBottom: 8 }}>
          {card.cost !== null && <div style={{ fontSize: 15, fontWeight: 700, border: "1px solid #000", borderRadius: 4, minWidth: 22, padding: "1px 3px" }}>{card.cost}</div>}
          <div style={{ fontSize: 14, fontWeight: 700 }}>{cardNameL(card)}</div>
        </div>
        {displayMode !== "noart" && <div style={{ display: "flex", justifyContent: "center", marginBottom: 10 }}><CardArt card={card} size={270} /></div>}
        {card.text && <div style={{ fontSize: 12, lineHeight: 1.4, color: "#333", marginBottom: 10 }}>{richCardText(card)}</div>}
        {card.type !== "spell" && (
          <div style={{ display: "flex", justifyContent: "center", gap: 24, marginBottom: 12, fontSize: 16, fontWeight: 700 }}>
            <div><div style={{ fontSize: 9, color: "#555" }}>{tr("ATK")}</div>{card.atk}</div>
            <div><div style={{ fontSize: 9, color: "#555" }}>{tr("HP")}</div>{card.hp}</div>
          </div>
        )}
        <button onClick={onClose} style={{ fontFamily: FONT, padding: "6px 18px", border: "2px solid #000", background: "#000", color: "#fff", cursor: "pointer", borderRadius: 4 }}>{tr("Close")}</button>
      </div>
    </div>
  );
}

function BoardMinion({ m, onClick, selected, targetable, isEnemy }) {
  const spent = !isEnemy && !m.canAttack;
  const cardDef = m.cardId ? findCard(m.cardId) : null;
  const rarity = cardDef ? cardDef.rarity : "common";
  const rStyle = RARITY_STYLE[rarity];
  const noArt = useDisplay().mode === "noart";
  const [showDetail, setShowDetail] = useState(false);
  const pressTimer = useRef(null);
  const longPressFired = useRef(false);

  const startPress = () => {
    longPressFired.current = false;
    pressTimer.current = setTimeout(() => {
      longPressFired.current = true;
      setShowDetail(true);
    }, 550);
  };
  const cancelPress = () => {
    if (pressTimer.current) { clearTimeout(pressTimer.current); pressTimer.current = null; }
  };
  const handleClick = () => {
    if (longPressFired.current) { longPressFired.current = false; return; }
    if (onClick) onClick();
  };
  const handleContextMenu = (e) => {
    e.preventDefault();
    setShowDetail(true);
  };

  return (
    <>
      <div
        data-tut-minion={m.name}
        data-tut-side={isEnemy ? "opp" : "me"}
        onClick={handleClick}
        onContextMenu={handleContextMenu}
        onMouseDown={startPress}
        onMouseUp={cancelPress}
        onMouseLeave={cancelPress}
        onTouchStart={startPress}
        onTouchEnd={cancelPress}
        onTouchMove={cancelPress}
        style={{
          width: 70, minWidth: 70, height: 92, border: `2px solid ${selected ? "#000" : targetable ? "#c0392b" : rStyle.border}`,
          borderRadius: 5, background: rStyle.bg, display: "flex", flexDirection: "column", alignItems: "center",
          padding: 3, cursor: onClick ? "pointer" : "default", position: "relative", fontFamily: FONT,
          boxShadow: selected ? "0 0 0 2px #000" : targetable ? "0 0 0 2px #c0392b" : "1px 1px 0 rgba(0,0,0,0.12)",
          opacity: spent ? 0.45 : 1, filter: spent ? "grayscale(60%)" : "none", userSelect: "none",
        }}
        title={tr("{card} (right-click or long-press for details)", { card: cardNameL(m) })}
      >
        <div style={{ position: "absolute", top: -8, left: "50%", transform: "translateX(-50%)", display: "flex", flexDirection: "column", alignItems: "center", gap: 2, zIndex: 2 }}>
          {m.shielded && <div style={{ fontSize: 8, background: "#fff", border: "1px solid #000", padding: "0 3px", borderRadius: 3, whiteSpace: "nowrap" }}>{tr("SHIELD")}</div>}
          {m.keywords.includes("Taunt") && <div style={{ fontSize: 8, background: "#000", color: "#fff", padding: "0 3px", borderRadius: 3, whiteSpace: "nowrap" }}>{tr("TAUNT")}</div>}
        </div>
        <CardArt card={m.cardId ? findCard(m.cardId) : { name: m.name, id: m.name }} size={46} />
        <div style={noArt ? { fontSize: 9.5, fontWeight: 700, textAlign: "center", marginTop: 6, lineHeight: 1.1, height: 44, overflow: "hidden", display: "flex", alignItems: "center", justifyContent: "center" } : { fontSize: 7, textAlign: "center", marginTop: 1, lineHeight: 1.05, height: 15, overflow: "hidden" }}>{cardNameL(m)}</div>
        {(isFrozenNow(m) || m.keywords.includes("Toxic")) && (
          <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 1, marginTop: 1 }}>
            {isFrozenNow(m) && <div style={{ fontSize: 6.5, lineHeight: 1, background: "#dbeeff", border: "1px solid #2a6ebb", padding: "0 3px", borderRadius: 3, whiteSpace: "nowrap" }}>{tr("FROZEN")}</div>}
            {m.keywords.includes("Toxic") && <div style={{ fontSize: 6.5, lineHeight: 1, background: "#39ff14", color: "#0a2e00", border: "1px solid #1a8a00", padding: "0 3px", borderRadius: 3, boxShadow: "0 0 4px rgba(57,255,20,0.8)", fontWeight: 700, whiteSpace: "nowrap" }}>{tr("TOXIC")}</div>}
          </div>
        )}
        <div style={{ marginTop: "auto", display: "flex", justifyContent: "space-between", width: "100%", fontSize: 12, fontWeight: 700 }}>
          <span>{m.atk}</span><span style={{ color: m.hp < m.maxHp ? "#c0392b" : "#000" }}>{m.hp}</span>
        </div>
        
      </div>
      {showDetail && <CardDetailModal card={cardLikeForMinion(m)} onClose={() => setShowDetail(false)} />}
    </>
  );
}

// right-click / long-press a hero to see their perks
function HeroPanel(props) { return <PerkPressArea player={props.player} owner={!props.isEnemy}><HeroPanelBase {...props} /></PerkPressArea>; }
function HeroPanelBase({ player, isEnemy, targetable, attackable, onClick, bgColor, api }) {
  const highlighted = targetable || attackable;
  const hpFrac = Math.max(0, Math.min(1, player.health / player.maxHealth));
  const barH = 58;
  const hideArt = useDisplay().mode === "noart";
  const redH = Math.round(barH * (1 - hpFrac));
  const greenH = barH - redH;
  return (
    <div
      data-dx-hero={isEnemy ? "opp" : "me"}
      onClick={onClick}
      style={{
        display: "flex", alignItems: "center", gap: 8, width: api ? 262 : 210, minWidth: api ? 262 : 210, height: 84, minHeight: 84, boxSizing: "border-box",
        border: `2px solid ${highlighted ? "#c0392b" : "#000"}`, borderRadius: 8, padding: "8px 10px",
        background: bgColor || "#fff", cursor: onClick ? "pointer" : "default", fontFamily: FONT,
        boxShadow: highlighted ? "0 0 0 2px #c0392b" : "1px 1px 0 rgba(0,0,0,0.12)",
        animation: attackable ? "heroAttackGlow 1.3s ease-in-out infinite" : "none",
      }}
    >
      <div style={{ width: 9, minWidth: 9, height: barH, border: "1px solid #000", borderRadius: 3, overflow: "hidden", flexShrink: 0, display: "flex", flexDirection: "column" }} title={tr("HP")}>
        <div style={{ height: redH, background: "#c0392b" }} />
        <div style={{ height: greenH, background: "#2ecc71" }} />
      </div>
      <div style={{ flex: 1, minWidth: 0 }}>
        <MarqueeText text={player.displayName ? `${heroL(player.hero)} ${player.displayName}` : heroL(player.hero)} width="100%" fontSize={12} bold duration={7} />
        <div style={{ fontSize: 9.5, whiteSpace: "nowrap" }}>
          {tr("HP:")} {Math.max(0, player.health)}{player.armor > 0 ? ` (+${player.armor})` : ""}<PerkStrip player={player} size={12} style={{ marginLeft: 6, verticalAlign: "middle" }} />
        </div>
        <div style={{ fontSize: 9.5, marginTop: 1, display: "flex", gap: 8, whiteSpace: "nowrap" }}>
          <span data-tut="ap">{tr("AP:")} {player.mana}/{player.maxMana}</span>
          <span>{tr("Deck:")} {player.deck.length}</span>
        </div>
        <div style={{ display: "flex", gap: 2, marginTop: 3 }} title={tr("{n} AP available", { n: player.mana })}>
          {Array.from({ length: 10 }).map((_, i) => {
            const filled = i < player.mana;
            return (
              <div
                key={i}
                style={{
                  width: 6.5, height: 6.5, borderRadius: "50%", flexShrink: 0,
                  background: filled ? "#39ff6a" : "#ccc",
                  boxShadow: filled ? "0 2px 4px rgba(57,255,106,0.7)" : "none",
                }}
              />
            );
          })}
        </div>
      </div>
      {api && <HandsBadge player={player} api={api} mine={!isEnemy} size={9.5} />}
      <div style={{ width: 50, height: 50, minWidth: 50, border: "1px solid #000", borderRadius: 6, background: "rgba(255,255,255,0.55)", display: hideArt ? "none" : "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, overflow: "hidden" }}>
        {HERO_ART_OVERRIDES[player.hero] ? (
          <img src={HERO_ART_OVERRIDES[player.hero]} alt={player.hero} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
        ) : (
          <span style={{ fontSize: 8, color: "#888" }}>IMG</span>
        )}
      </div>
    </div>
  );
}

/* ---------- ranked tiers ---------- */
const TIERS = ["Bronze", "Silver", "Gold", "Legendary"];
function currentMonthKey() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
}
// NOTE: the function that used to live here (applyMatchResult, which turns
// a win/loss into updated wins/tier/streaks) now runs ONLY server-side, in
// functions/gameLogic.js, as part of the claimMatchReward Cloud Function -
// see that file for the real logic (including the monthly tier reset). The
// client no longer computes or writes tier/streak changes itself; it just
// displays whatever the server last confirmed (myProfile, via the
// onSnapshot listener below).
// A player's displayed "this month" stats, adjusted for month rollover even
// if they haven't played yet this month (so it never shows stale data).
function monthStatsFor(profile) {
  const mk = currentMonthKey();
  if (!profile || profile.monthKey !== mk) return { monthWins: 0, monthLosses: 0 };
  return { monthWins: profile.monthWins || 0, monthLosses: profile.monthLosses || 0 };
}
function ratioFor(wins, losses) {
  return losses === 0 ? wins : wins / losses;
}

/* =========================================================================
   QUESTS — 5 of 10 possible quests are active each week, chosen (and their
   numeric targets randomized) by a seed derived from Eastern Time, so every
   player sees the exact same 5 quests with the exact same targets without
   needing a server or scheduled job — same seed in, same result out, always.
   Rotates every Sunday at 20:00 Eastern Time.
   ========================================================================= */
const QUEST_POOL = [
  { id: "grinder", title: "Atomic Grinder", type: "gamesPlayed", min: 25, max: 35, verb: "Play", noun: "games" },
  { id: "warrior", title: "Feared Warrior", type: "wins", min: 15, max: 20, verb: "Win", noun: "games" },
  { id: "shuffler", title: "Casino Shuffler", type: "neutralCardsPlayed", min: 500, max: 600, verb: "Play", noun: "neutral cards" },
  { id: "overpowered", title: "Overpowered", type: "uniqueCardsPlayed", min: 60, max: 80, verb: "Play", noun: "unique cards" },
  { id: "purple", title: "Purple Monster", type: "epicCardsPlayed", min: 200, max: 250, verb: "Play", noun: "epic cards" },
  { id: "medalist", title: "Wasteland Medalist", type: "tier" },
  { id: "nemesis", title: "Nemesis", type: "heroDefeats", min: 5, max: 8, randomHero: true, verb: "Defeat", noun: "times" },
  { id: "comedy", title: "Comedy Gold", type: "cardPlays", cardName: "Jim, King of Comedy", min: 10, max: 15, verb: "Play", noun: "times" },
  { id: "armored", title: "Armored", type: "armorGained", min: 150, max: 175, verb: "Gain", noun: "armor" },
  { id: "firstaid", title: "First Aid Expert", type: "healthRestored", min: 200, max: 250, verb: "Restore", noun: "health" },
];
const QUEST_BULLET_REWARD = 100;
const QUEST_COLORS = ["#fde3c4", "#e6dcf7", "#dcf3d9", "#d9ecfb", "#fbdcdc", "#fff2b3", "#d5f5f0", "#f7d9ec"];

function mulberry32(seed) {
  return function () {
    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function questWeekId(date = new Date()) {
  const et = new Date(date.toLocaleString("en-US", { timeZone: "America/New_York" }));
  const shifted = new Date(et.getTime() - 20 * 60 * 60 * 1000); // shift so the boundary becomes Sunday 20:00 ET
  const day = shifted.getDay();
  const sunday = new Date(shifted);
  sunday.setDate(shifted.getDate() - day);
  sunday.setHours(0, 0, 0, 0);
  const epoch = new Date(2020, 0, 1);
  return Math.floor((sunday - epoch) / (7 * 24 * 60 * 60 * 1000));
}
function selectWeeklyQuests(weekId) {
  const rng = mulberry32(weekId);
  const pool = QUEST_POOL.map((q) => ({ ...q }));
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  return pool.slice(0, 5).map((q, i) => ({
    ...q,
    target: q.min !== undefined ? q.min + Math.floor(rng() * (q.max - q.min + 1)) : null,
    hero: q.randomHero ? HEROES[Math.floor(rng() * HEROES.length)] : null,
    color: QUEST_COLORS[i % QUEST_COLORS.length],
  }));
}
function questDescription(q) {
  if (q.type === "tier") return tr("Reach Gold rank.");
  if (q.type === "heroDefeats") return tr("Defeat {hero} {n} times.", { hero: heroL(q.hero), n: q.target });
  if (q.type === "cardPlays") return tr("Play {card} {n} times.", { card: cardNameL(q.cardName), n: q.target });
  return tr(`${q.verb} {n} ${q.noun}.`, { n: q.target });
}
function questProgress(q, weeklyProgress, tier) {
  if (q.type === "tier") {
    const done = TIERS.indexOf(tier || "Bronze") >= TIERS.indexOf("Gold");
    return { current: done ? 1 : 0, target: 1, done };
  }
  if (q.type === "heroDefeats") {
    const current = (weeklyProgress.heroDefeats && weeklyProgress.heroDefeats[q.hero]) || 0;
    return { current, target: q.target, done: current >= q.target };
  }
  if (q.type === "cardPlays") {
    const current = (weeklyProgress.cardPlays && weeklyProgress.cardPlays[q.cardName]) || 0;
    return { current, target: q.target, done: current >= q.target };
  }
  const current = weeklyProgress[q.type] || 0;
  return { current, target: q.target, done: current >= q.target };
}
// Fresh/rolled-over weekly progress bucket for a given weekId.
function freshWeeklyProgress(weekId) {
  return { weekId, gamesPlayed: 0, wins: 0, neutralCardsPlayed: 0, epicCardsPlayed: 0, uniqueCardsPlayed: 0, armorGained: 0, healthRestored: 0, heroDefeats: {}, cardPlays: {}, claimedQuestIds: [] };
}
function weeklyProgressFor(profile) {
  const wk = questWeekId();
  if (!profile || !profile.weeklyProgress || profile.weeklyProgress.weekId !== wk) return freshWeeklyProgress(wk);
  return profile.weeklyProgress;
}

const TIER_STYLES = {
  Bronze: { gradient: "linear-gradient(160deg, #e0a868, #9c5f22)", glow: "0 6px 18px rgba(180,110,40,0.5)", text: "#3a2308" },
  Silver: { gradient: "linear-gradient(160deg, #f2f2f2, #a8a8a8)", glow: "0 6px 18px rgba(170,170,170,0.55)", text: "#2b2b2b" },
  Gold: { gradient: "linear-gradient(160deg, #ffe38a, #c99a2e)", glow: "0 6px 18px rgba(255,205,60,0.6)", text: "#3a2a00" },
  Legendary: { gradient: "linear-gradient(160deg, #f7c8ff, #8a2be2)", glow: "0 6px 22px rgba(150,50,230,0.65)", text: "#fff" },
};

function TierFrame({ profile }) {
  const tier = profile.tier || "Bronze";
  const style = TIER_STYLES[tier];
  const isTop = tier === "Legendary";
  const onLossStreak = (profile.lossStreak || 0) > 0;
  const canDemote = TIERS.indexOf(tier) > 0;
  return (
    <div style={{ background: style.gradient, boxShadow: style.glow, borderRadius: 12, border: "2px solid #000", padding: "16px 18px", textAlign: "center", color: style.text, marginTop: 14 }}>
      <div style={{ fontSize: 11, opacity: 0.85, letterSpacing: 1 }}>{tr("YOUR TIER")}</div>
      <div style={{ fontSize: 26, fontWeight: 700, letterSpacing: 1 }}>{tierL(tier)}</div>
      {!isTop && !onLossStreak && (
        <div style={{ fontSize: 12, marginTop: 6 }}>
          {tr("{n} more wins in a row to reach {tier}", { n: 5 - (profile.winStreak || 0), tier: tierL(TIERS[TIERS.indexOf(tier) + 1]) })}
        </div>
      )}
      {onLossStreak && canDemote && (
        <div style={{ fontSize: 12, marginTop: 6, fontWeight: 700, color: "#7a1010" }}>
          {tr("{n} more losses in a row and you'll drop to {tier}", { n: 5 - profile.lossStreak, tier: tierL(TIERS[TIERS.indexOf(tier) - 1]) })}
        </div>
      )}
      {onLossStreak && !canDemote && (
        <div style={{ fontSize: 12, marginTop: 6 }}>{tr("Bronze is the floor — no further demotion.")}</div>
      )}
    </div>
  );
}

function LegendaryLeaderboard({ myUid }) {
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [visibleCount, setVisibleCount] = useState(50);
  const CAP = 250;

  useEffect(() => {
    (async () => {
      try {
        const snap = await getDocs(query(collection(db, "users"), where("tier", "==", "Legendary"), limit(500)));
        const list = snap.docs.map((d) => {
          const data = d.data();
          const { monthWins, monthLosses } = monthStatsFor(data);
          return { id: d.id, displayName: data.displayName || tr("Player"), monthWins, monthLosses, ratio: ratioFor(monthWins, monthLosses) };
        });
        list.sort((a, b) => b.ratio - a.ratio || b.monthWins - a.monthWins);
        setRows(list.slice(0, CAP));
      } catch (e) {
        console.error("Legendary leaderboard load failed:", e);
      }
      setLoading(false);
    })();
  }, []);

  const myRankIdx = rows.findIndex((r) => r.id === myUid);
  const visible = rows.slice(0, visibleCount);
  const canShowMore = visibleCount < rows.length;

  return (
    <div style={{ marginTop: 16, background: "linear-gradient(165deg, #eafeff, #bdeeff 45%, #59c8f5)", boxShadow: "0 0 26px rgba(89,200,245,0.7)", border: "2px solid #0a7fb0", borderRadius: 12, padding: 16 }}>
      <div style={{ fontWeight: 700, fontSize: 15, textAlign: "center", color: "#043a52" }}>{tr("⬦ Legendary League — This Month ⬦")}</div>
      {loading ? (
        <p style={{ fontSize: 12, textAlign: "center" }}>{tr("Loading...")}</p>
      ) : rows.length === 0 ? (
        <p style={{ fontSize: 12, textAlign: "center", color: "#043a52" }}>{tr("No Legendary players yet this month.")}</p>
      ) : (
        <>
          {myRankIdx !== -1 && (
            <div style={{ fontSize: 12, fontWeight: 700, textAlign: "center", margin: "8px 0", color: "#043a52" }}>
              {tr("YOUR CURRENT RANK: #{n}", { n: myRankIdx + 1 })}
            </div>
          )}
          <table style={{ width: "100%", fontSize: 12, borderCollapse: "collapse", marginTop: 8, background: "rgba(255,255,255,0.6)", borderRadius: 6 }}>
            <thead>
              <tr style={{ textAlign: "left", borderBottom: "2px solid #0a7fb0" }}>
                <th style={{ padding: "4px 6px" }}>#</th>
                <th style={{ padding: "4px 6px" }}>{tr("Player")}</th>
                <th style={{ padding: "4px 6px", textAlign: "center" }}>{tr("W")}</th>
                <th style={{ padding: "4px 6px", textAlign: "center" }}>{tr("L")}</th>
                <th style={{ padding: "4px 6px", textAlign: "center" }}>{tr("Ratio")}</th>
              </tr>
            </thead>
            <tbody>
              {visible.map((r, i) => (
                <tr key={r.id} style={{ borderTop: "1px solid #bcdff0", fontWeight: r.id === myUid ? 700 : 400, background: r.id === myUid ? "rgba(10,127,176,0.15)" : "none" }}>
                  <td style={{ padding: "4px 6px" }}>{i + 1}</td>
                  <td style={{ padding: "4px 6px" }}>{r.displayName}</td>
                  <td style={{ padding: "4px 6px", textAlign: "center" }}>{r.monthWins}</td>
                  <td style={{ padding: "4px 6px", textAlign: "center" }}>{r.monthLosses}</td>
                  <td style={{ padding: "4px 6px", textAlign: "center" }}>{r.ratio.toFixed(2)}</td>
                </tr>
              ))}
            </tbody>
          </table>
          {canShowMore && (
            <div style={{ textAlign: "center", marginTop: 10 }}>
              <button
                onClick={() => setVisibleCount((v) => Math.min(v + 50, CAP))}
                style={{ fontFamily: FONT, padding: "6px 16px", border: "2px solid #0a7fb0", background: "#fff", color: "#043a52", cursor: "pointer", borderRadius: 4, fontWeight: 700 }}
              >
                {tr("Show More")}</button>
            </div>
          )}
        </>
      )}
    </div>
  );
}

function LeaderboardScreen({ onBack, myProfile, sessionId, profileLoading }) {
  const p = myProfile || { wins: 0, losses: 0, winStreak: 0, lossStreak: 0, tier: "Bronze" };
  const { monthWins, monthLosses } = monthStatsFor(p);

  if (profileLoading) {
    return (
      <div style={{ fontFamily: FONT, padding: 20, maxWidth: 640, margin: "0 auto" }}>
        <h2 style={{ fontSize: 18, borderBottom: "2px solid #000", paddingBottom: 6 }}>{tr("Leaderboard")}</h2>
        <p style={{ fontSize: 13, color: "#666", marginTop: 12 }}>{tr("Loading your stats...")}</p>
      </div>
    );
  }

  return (
    <div style={{ fontFamily: FONT, padding: 20, maxWidth: 640, margin: "0 auto" }}>
      <h2 style={{ fontSize: 18, borderBottom: "2px solid #000", paddingBottom: 6 }}>{tr("Leaderboard")}</h2>
      <WinRewardPanel profile={p} />

      <div style={{ fontSize: 11, color: "#666", marginTop: 12, letterSpacing: 1 }}>{tr("ALL-TIME")}</div>
      <div style={{ display: "flex", gap: 18, marginTop: 4, fontSize: 13 }}>
        <div><b>{p.wins || 0}</b> {tr("Wins")}</div>
        <div><b>{p.losses || 0}</b> {tr("Losses")}</div>
        <div><b>{tierL(p.highestTier || "Bronze")}</b> {tr("Highest Tier")}</div>
      </div>

      <div style={{ fontSize: 11, color: "#666", marginTop: 12, letterSpacing: 1 }}>{tr("THIS MONTH")}</div>
      <div style={{ display: "flex", gap: 18, marginTop: 4, fontSize: 13, flexWrap: "wrap" }}>
        <div><b>{monthWins}</b> {tr("Wins")}</div>
        <div><b>{monthLosses}</b> {tr("Losses")}</div>
        <div><b>{p.winStreak || 0}</b> {tr("Win Streak")}</div>
        <div><b>{ratioFor(monthWins, monthLosses).toFixed(2)}</b> {tr("Ratio")}</div>
      </div>

      <TierFrame profile={p} />

      {p.tier === "Legendary" && <LegendaryLeaderboard myUid={sessionId} />}

      <div style={{ marginTop: 16 }}>

      </div>
    </div>
  );
}

/* ---------- Hero select screen ---------- */
function QuestsScreen({ onBack, myProfile, profileLoading }) {
  const wp = weeklyProgressFor(myProfile);
  const tier = myProfile ? (myProfile.tier || "Bronze") : "Bronze";
  const quests = selectWeeklyQuests(wp.weekId);
  const claimed = new Set(wp.claimedQuestIds || []);

  if (profileLoading) {
    return (
      <div style={{ fontFamily: FONT, padding: 20, maxWidth: 640, margin: "0 auto" }}>
        <h2 style={{ fontSize: 18, borderBottom: "2px solid #000", paddingBottom: 6 }}>{tr("Weekly Quests")}</h2>
        <p style={{ fontSize: 13, color: "#666", marginTop: 12 }}>{tr("Loading your progress...")}</p>
      </div>
    );
  }

  return (
    <div style={{ fontFamily: FONT, padding: 20, maxWidth: 640, margin: "0 auto" }}>
      <h2 style={{ fontSize: 18, borderBottom: "2px solid #000", paddingBottom: 6 }}>{tr("Weekly Quests")}</h2>
      <p style={{ fontSize: 11, color: "#666", marginTop: 6 }}>
        {tr("5 quests, refreshed every Sunday at 8:00 PM Eastern. Each completed quest pays out {n} Bullets.", { n: QUEST_BULLET_REWARD })}
      </p>
      <div style={{ display: "flex", flexDirection: "column", gap: 10, marginTop: 14 }}>
        {quests.map((q) => {
          const done = claimed.has(q.id) || questProgress(q, wp, tier).done;
          const prog = questProgress(q, wp, tier);
          return (
            <div key={q.id} style={{
              position: "relative", border: "2px solid #000", borderRadius: 10, padding: 14,
              background: done ? "#ddd" : q.color, opacity: done ? 0.6 : 1,
            }}>
              {done && (
                <div style={{ position: "absolute", top: -10, left: 12, background: "#fff", padding: "0 6px", color: "#c0392b", fontWeight: 700, fontSize: 12, border: "2px solid #c0392b", borderRadius: 4 }}>
                  {tr("Completed")}</div>
              )}
              <div style={{ fontSize: 17, fontWeight: 700, marginTop: done ? 6 : 0 }}>{tr(q.title)}</div>
              <div style={{ fontSize: 12, marginTop: 4, color: "#333" }}>{questDescription(q)}</div>
              <div style={{ fontSize: 12, marginTop: 6, fontWeight: 700 }}>
                {Math.min(prog.current, prog.target)} / {prog.target}
              </div>
            </div>
          );
        })}
      </div>

    </div>
  );
}

// Rough locale-based guess only - NOT real IP geolocation. Good enough to
// show a plausible currency symbol; a real payment provider would determine
// this properly at checkout time.
function guessCurrency() {
  try {
    const locale = (Intl.NumberFormat().resolvedOptions().locale || navigator.language || "en-US");
    const region = (locale.split("-")[1] || "").toUpperCase();
    const euroRegions = ["AT", "BE", "CY", "EE", "FI", "FR", "DE", "GR", "IE", "IT", "LV", "LT", "LU", "MT", "NL", "PT", "SK", "SI", "ES", "HR"];
    return euroRegions.includes(region) ? "EUR" : "USD";
  } catch (e) {
    return "USD";
  }
}

// Replace with your real Google account email(s) before deploying. This
// gates the UI only - see the deployment notes on why the Firestore rules
// ALSO need updating for this to be a genuine security boundary.
const ADMIN_EMAILS = ["janhorak2000@gmail.com"];

function AdminGrantPanel() {
  const [amount, setAmount] = useState("");
  const [emailsText, setEmailsText] = useState("");
  const [running, setRunning] = useState(false);
  const [results, setResults] = useState(null);
  const [progress, setProgress] = useState(0);

  async function runGrant() {
    const amt = parseInt(amount, 10);
    const emails = emailsText.split(/[\n,;]+/).map((e) => e.trim()).filter(Boolean);
    if (!amt || amt <= 0 || emails.length === 0) return;
    setRunning(true);
    setResults(null);
    setProgress(0);
    const out = [];
    for (let i = 0; i < emails.length; i++) {
      const email = emails[i];
      try {
        await callAdminGrantBullets({ email, amount: amt });
        out.push({ email, ok: true, reason: "" });
      } catch (e) {
        out.push({ email, ok: false, reason: (e && e.message) || "grant failed" });
      }
      setProgress(i + 1);
    }
    setResults(out);
    setRunning(false);
  }

  const [hideMsg, setHideMsg] = useState("");
  async function hideEmails() {
    setHideMsg("Working...");
    try { const r = await callAdminHideEmails(); setHideMsg(`Done - ${r.data.moved} of ${r.data.total} profiles cleaned. Emails are now private.`); }
    catch (e) { setHideMsg("Failed: " + ((e && e.message) || e)); }
  }

  return (
    <div style={{ marginTop: 10 }}>
      <div style={{ marginBottom: 14, padding: 8, border: "1px dashed #999", borderRadius: 4 }}>
        <button type="button" onClick={hideEmails} style={{ fontFamily: FONT, fontSize: 12, padding: "5px 10px", border: "2px solid #000", borderRadius: 4, background: "#fff", cursor: "pointer" }}>Hide stored emails (one-time clean-up)</button>
        {hideMsg && <div style={{ fontSize: 11, marginTop: 6 }}>{hideMsg}</div>}
      </div>
      <p style={{ fontSize: 11, color: "#333" }}>Bullet amount to grant to each account:</p>
      <input
        type="number" value={amount} onChange={(e) => setAmount(e.target.value)}
        style={{ fontFamily: FONT, fontSize: 13, padding: "6px 8px", border: "2px solid #000", borderRadius: 4, width: 140 }}
      />
      <p style={{ fontSize: 11, color: "#333", marginTop: 10 }}>Email addresses (one per line, or comma-separated - works for a large batch at once):</p>
      <textarea
        value={emailsText} onChange={(e) => setEmailsText(e.target.value)}
        rows={6}
        style={{ fontFamily: FONT, fontSize: 12, padding: 8, border: "2px solid #000", borderRadius: 4, width: "100%", boxSizing: "border-box" }}
        placeholder={"player1@example.com\nplayer2@example.com"}
      />
      <button
        onClick={runGrant}
        disabled={running}
        style={{ marginTop: 8, padding: "8px 16px", fontFamily: FONT, fontWeight: 700, border: "2px solid #000", background: running ? "#ccc" : "#000", color: "#fff", cursor: running ? "default" : "pointer", borderRadius: 4 }}
      >
        {running ? `Working... (${progress})` : "Grant Bullets"}
      </button>
      {results && (
        <div style={{ marginTop: 12, fontSize: 11, maxHeight: 200, overflowY: "auto", border: "1px solid #ccc", borderRadius: 4, padding: 8 }}>
          {results.map((r, i) => (
            <div key={i} style={{ color: r.ok ? "#1a7a1a" : "#c0392b" }}>
              {r.ok ? "✓" : "✗"} {r.email} {r.reason ? `— ${r.reason}` : ""}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

