function DeckBuilderScreen({ hero, initialDeck, onSave, onCancel, myProfile, onBuyCard }) {
  const pool = CARD_DB.filter((c) => c.hero === hero || !c.hero);
  const [deckView, setDeckView] = useState("normal");
  const [counts, setCounts] = useState(() => {
    const c = {};
    if (initialDeck) initialDeck.forEach((id) => { c[id] = (c[id] || 0) + 1; });
    return c;
  });
  const [saveError, setSaveError] = useState(null);
  const [lockedCardClicked, setLockedCardClicked] = useState(null);
  const total = Object.values(counts).reduce((a, b) => a + b, 0);
  const rarityOrder = ["common", "rare", "epic", "unique"];

  function addCopy(card) {
    const cur = counts[card.id] || 0;
    if (cur >= card.copies || total >= 30) return;
    setCounts({ ...counts, [card.id]: cur + 1 });
  }
  function removeCopy(cardId) {
    const cur = counts[cardId] || 0;
    if (cur <= 1) { const next = { ...counts }; delete next[cardId]; setCounts(next); }
    else setCounts({ ...counts, [cardId]: cur - 1 });
  }
  function handleSave() {
    const deck = Object.entries(counts).flatMap(([id, n]) => Array(n).fill(id));
    if (!validateDeck(deck, hero)) {
      setSaveError(tr("This deck isn't legal — check you have exactly 30 cards, only cards for this hero or neutrals, and no more copies than allowed."));
      return;
    }
    setSaveError(null);
    onSave(deck);
  }

  const heroCards = pool.filter((c) => c.hero === hero);
  const neutralCards = pool.filter((c) => !c.hero);
  const deckEntries = Object.entries(counts).filter(([, n]) => n > 0)
    .map(([id, n]) => ({ card: findCard(id), n }))
    .sort((a, b) => a.card.cost - b.card.cost);

  function renderSection(groupLabel, cards) {
    return (
      <div key={groupLabel}>
        {rarityOrder.map((r) => {
          const group = cards.filter((c) => c.rarity === r && (deckView !== "diamond" || myDiamondCount(myProfile, c.id) > 0)).sort((a, b) => a.cost - b.cost);
          if (group.length === 0) return null;
          const rarityLabel = tr(r.charAt(0).toUpperCase() + r.slice(1));
          return (
            <div key={r}>
              <div style={{ fontWeight: 700, marginTop: 14, marginBottom: 6, fontSize: 12 }}>
                {tr("Standard Set")} · {rarityLabel} · {groupLabel}
              </div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
                {group.map((c) => {
                  const cnt = counts[c.id] || 0;
                  const atCap = cnt >= c.copies;
                  const deckFull = total >= 30;
                  const locked = !isCardUnlocked(c, myProfile);
                  return (
                    <div
                      key={c.id}
                      style={{ position: "relative", opacity: locked ? 0.4 : 1, filter: locked ? "grayscale(70%)" : "none" }}
                      onClick={() => { if (locked) openCardManage(c); else addCopy(c); }}
                    >
                      <MiniCard cardId={c.id} small disabled={atCap || deckFull || locked} allowDetail diamond={deckView === "diamond"} />
                      {locked && <div style={{ position: "absolute", top: -6, left: -6, fontSize: 8, background: "#c0392b", color: "#fff", padding: "1px 4px", borderRadius: 3, fontWeight: 700 }}>{tr("LOCKED")}</div>}
                      {!locked && cnt > 0 && <div style={{ position: "absolute", top: -6, right: -6, background: "#000", color: "#fff", borderRadius: "50%", width: 18, height: 18, fontSize: 10, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: FONT, border: "1px solid #fff" }}>{cnt}</div>}
                      {!locked && (canSellNormalCard(c, myProfile) || myDiamondCount(myProfile, c.id) > 0) && (
                        <button type="button" title={tr("Sell")} onClick={(e) => { e.stopPropagation(); openCardManage(c); }} style={{ position: "absolute", left: -6, bottom: -6, width: 20, height: 20, borderRadius: "50%", border: "1px solid #000", background: "#ffd24a", fontFamily: FONT, fontWeight: 900, fontSize: 11, cursor: "pointer", padding: 0, zIndex: 3 }}>$</button>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    );
  }

  return (
    <div style={{ fontFamily: FONT, padding: 16, maxWidth: 900, margin: "0 auto" }}>
      <h2 style={{ fontSize: 18, borderBottom: "2px solid #000", paddingBottom: 6 }}>{tr("Deck Builder")} — {heroL(hero)}</h2>
      <DeckViewToggle view={deckView} setView={setDeckView} profile={myProfile} />
      <div style={{ fontSize: 12, color: "#555", marginTop: 4 }}>{tr("Tap a card to add a copy. Tap a card in \"Your Deck\" to remove one. Max 2 copies (1 for uniques).")}</div>
      <div style={{ display: "flex", gap: 18, flexWrap: "wrap", marginTop: 10 }}>
        <div style={{ flex: 2, minWidth: 280, maxHeight: 480, overflowY: "auto", paddingRight: 6 }}>
          {renderSection(tr("{hero}'s cards", { hero: heroL(hero) }), heroCards)}
          {renderSection(tr("Neutral cards"), neutralCards)}
        </div>
        <div style={{ flex: 1, minWidth: 220, borderLeft: "1px solid #ccc", paddingLeft: 14 }}>
          <div style={{ fontWeight: 700, marginBottom: 6, fontSize: 13, color: total === 30 ? "#1a7a1a" : "#c0392b" }}>{tr("Your Deck")} — {total}/30</div>
          <div style={{ maxHeight: 420, overflowY: "auto" }}>
            {deckEntries.length === 0 && <div style={{ fontSize: 11, color: "#888" }}>{tr("No cards yet — tap cards on the left to add them.")}</div>}
            {deckEntries.map(({ card, n }) => (
              <div key={card.id} onClick={() => removeCopy(card.id)} style={{ display: "flex", justifyContent: "space-between", fontSize: 11, padding: "4px 2px", borderBottom: "1px solid #eee", cursor: "pointer" }} title={tr("Click to remove one copy")}>
                <span>[{card.cost}] {cardNameL(card)}</span>
                <span>x{n}</span>
              </div>
            ))}
          </div>
        </div>
      </div>
      <div style={{ marginTop: 16, display: "flex", gap: 10, alignItems: "center" }}>
        <button
          disabled={total !== 30}
          onClick={handleSave}
          style={{ padding: "10px 18px", fontFamily: FONT, fontSize: 13, fontWeight: 700, border: "2px solid #000", background: total === 30 ? "#000" : "#ccc", color: "#fff", cursor: total === 30 ? "pointer" : "default", borderRadius: 4 }}
        >
          {tr("Save deck")} ({total}/30)
        </button>
        <button onClick={() => setCounts({})} style={{ padding: "10px 14px", fontFamily: FONT, fontSize: 13, border: "2px solid #000", background: "#fff", cursor: "pointer", borderRadius: 4 }}>{tr("Clear")}</button>
        <button onClick={onCancel} style={{ padding: "10px 14px", fontFamily: FONT, fontSize: 13, border: "2px solid #000", background: "#fff", cursor: "pointer", borderRadius: 4 }}>{tr("Cancel")}</button>
      </div>
      {saveError && <div style={{ marginTop: 8, fontSize: 11, color: "#c0392b", background: "#fff3f2", border: "1px solid #c0392b", padding: "6px 8px", borderRadius: 4 }}>{saveError}</div>}
      {lockedCardClicked && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.55)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 200 }} onClick={() => setLockedCardClicked(null)}>
          <div onClick={(e) => e.stopPropagation()} style={{ background: "#fff", border: "2px solid #000", borderRadius: 8, padding: 20, textAlign: "center", maxWidth: 300 }}>
            <div style={{ fontWeight: 700, fontSize: 15 }}>{tr("{name} is locked", { name: cardNameL(lockedCardClicked) })}</div>
            <p style={{ fontSize: 12, color: "#555", marginTop: 8 }}>
              {tr("Unlock this card for {n} Bullets. Need more? Visit the Shop to buy Bullets or unlock a whole hero at once.", { n: CARD_UNLOCK_COST[lockedCardClicked.rarity] })}
            </p>
            <div style={{ display: "flex", gap: 8, justifyContent: "center", marginTop: 14, flexWrap: "wrap" }}>
              <button
                onClick={() => { onBuyCard(lockedCardClicked); setLockedCardClicked(null); }}
                disabled={(myProfile?.bullets || 0) < CARD_UNLOCK_COST[lockedCardClicked.rarity]}
                style={{ fontFamily: FONT, fontWeight: 700, padding: "8px 16px", border: "2px solid #000", background: (myProfile?.bullets || 0) < CARD_UNLOCK_COST[lockedCardClicked.rarity] ? "#ccc" : "#000", color: "#fff", cursor: (myProfile?.bullets || 0) < CARD_UNLOCK_COST[lockedCardClicked.rarity] ? "default" : "pointer", borderRadius: 4 }}
              >
                {tr("Buy for {n} Bullets", { n: CARD_UNLOCK_COST[lockedCardClicked.rarity] })}
              </button>
              <button onClick={() => setLockedCardClicked(null)} style={{ fontFamily: FONT, padding: "8px 16px", border: "2px solid #000", background: "#fff", cursor: "pointer", borderRadius: 4 }}>{tr("Close")}</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function SearchingScreen({ hero, onCancel }) {
  const [dots, setDots] = useState("");
  useEffect(() => {
    const t = setInterval(() => setDots((d) => (d.length >= 3 ? "" : d + ".")), 500);
    return () => clearInterval(t);
  }, []);
  return (
    <div style={{ fontFamily: FONT, padding: 30, textAlign: "center" }}>
      <h2>{tr("Searching for opponent")}{dots}</h2>
      <p style={{ fontSize: 12, color: "#555" }}>{tr("Playing as {hero}. Checks the queue every couple seconds — no need to keep this tab focused.", { hero: heroL(hero) })}</p>
      <button onClick={onCancel} style={{ marginTop: 16, fontFamily: FONT, padding: "6px 14px", border: "2px solid #000", background: "#fff", cursor: "pointer" }}>{tr("Cancel")}</button>
    </div>
  );
}

/* ---------- Main game screen ---------- */
// Merges the live board with recently-dead minions still fading out, keeping
// everyone in their ORIGINAL relative position. Without this, a dying ghost
// rendered as a separate trailing list would appear to jump to the end of
// the row the instant the live board reflows around the gap it left behind.
function useBoardWithGhosts(board) {
  const [merged, setMerged] = useState(() => board.map((m) => ({ ...m, __dying: false })));
  const timersRef = useRef({});

  useEffect(() => {
    setMerged((prevMerged) => {
      const liveByUid = new Map(board.map((m) => [m.uid, m]));
      const prevUids = new Set(prevMerged.map((m) => m.uid));

      const next = prevMerged.map((entry) => {
        const live = liveByUid.get(entry.uid);
        if (live) return { ...live, __dying: false };
        if (!entry.__dying) {
          if (!timersRef.current[entry.uid]) {
            timersRef.current[entry.uid] = setTimeout(() => {
              setMerged((cur) => cur.filter((x) => x.uid !== entry.uid));
              delete timersRef.current[entry.uid];
            }, 1000);
          }
          return { ...entry, __dying: true };
        }
        return entry;
      });

      board.forEach((m) => { if (!prevUids.has(m.uid)) next.push({ ...m, __dying: false }); });
      return next;
    });
  }, [board]);

  useEffect(() => () => { Object.values(timersRef.current).forEach(clearTimeout); }, []);

  return merged;
}

function GameScreen({ state, myIdx, onAction, onConcede, actionError, onSync, onBackToMenu, isCpuMatch }) {
  const me = state.players[myIdx];
  const opp = state.players[myIdx === 0 ? 1 : 0];
  const myTurn = state.turn === myIdx;
  const display = useDisplay();
  const tutS = useTut();
  const [pending, setPending] = useState(null); // {kind:'card'|'power', idx?, needsTarget}
  const [attacker, setAttacker] = useState(null); // uid of selected attacking minion
  const [confirmingIdx, setConfirmingIdx] = useState(null); // hand index awaiting Yes/No confirmation
  const [confirmConcede, setConfirmConcede] = useState(false);
  const [notice, setNotice] = useState(null); // transient feedback message
  const noticeTimer = useRef(null);
  const [, forceTick] = useState(0);
  const afkFiredRef = useRef(null);
  const mulliganFiredRef = useRef(null);
  const [mulliganSelected, setMulliganSelected] = useState([]);
  const [discoverSelected, setDiscoverSelected] = useState(null);
  useEffect(() => { setDiscoverSelected(null); }, [state.pendingDiscover ? state.pendingDiscover.options.join(",") : null]);

  const cancelPending = () => { setPending(null); setAttacker(null); };
  const MULLIGAN_MAX = 2;
  const toggleMulliganCard = (handIdx) => {
    setMulliganSelected((prev) => {
      if (prev.includes(handIdx)) return prev.filter((i) => i !== handIdx);
      if (prev.length >= MULLIGAN_MAX) return prev;
      return [...prev, handIdx];
    });
  };
  const confirmMulligan = () => onAction({ type: "mulligan", cardIds: mulliganSelected.map((idx) => me.hand[idx]) });
  const flash = (msg) => {
    setNotice(msg);
    if (noticeTimer.current) clearTimeout(noticeTimer.current);
    noticeTimer.current = setTimeout(() => setNotice(null), 2200);
  };
  useEffect(() => () => { if (noticeTimer.current) clearTimeout(noticeTimer.current); }, []);

  // Mulligan: only on this player's own very first turn (turnNumber 1 for
  // whoever goes first, 2 for whoever goes second), before they've resolved it.
  const isMyFirstTurn = state.turnNumber === myIdx + 1;
  const mulliganElapsed = state.turnStartedAt ? Date.now() - state.turnStartedAt : 0;
  const showMulligan = myTurn && isMyFirstTurn && !me.mulliganDone && state.winner === null && mulliganElapsed < 15000;

  useEffect(() => { setMulliganSelected([]); }, [state.turnNumber]);

  // Turn timer: re-render once a second so countdown UI stays live. The hard
  // 2-minute AFK cutoff is skipped for CPU matches, but the mulligan
  // auto-timeout still applies (a human should still get their mulligan
  // window even when playing solo against the bot).
  useEffect(() => {
    const timer = setInterval(() => {
      forceTick((x) => x + 1);
      if (!state.turnStartedAt || state.winner !== null) return;
      const elapsed = Date.now() - state.turnStartedAt;
      if (myTurn && isMyFirstTurn && !me.mulliganDone && elapsed >= 15000 && mulliganFiredRef.current !== state.turnStartedAt) {
        mulliganFiredRef.current = state.turnStartedAt;
        onAction({ type: "mulligan", cardIds: [] });
        return;
      }
      if (isCpuMatch) return;
      if (elapsed >= 120000 && afkFiredRef.current !== state.turnStartedAt) {
        afkFiredRef.current = state.turnStartedAt;
        onAction({ type: "afkTimeout" });
      }
    }, 1000);
    return () => clearInterval(timer);
  }, [isCpuMatch, state.turnStartedAt, state.winner, myTurn, isMyFirstTurn, me.mulliganDone]);

  const turnElapsed = state.turnStartedAt ? Date.now() - state.turnStartedAt : 0;
  const showIdleWarning = !isCpuMatch && !showMulligan && myTurn && state.winner === null && turnElapsed >= 60000 && turnElapsed < 120000;
  const showOpponentIdleNote = !isCpuMatch && !myTurn && state.winner === null && turnElapsed >= 60000;

  const oppBoardWithGhosts = useBoardWithGhosts(opp.board);
  const meBoardWithGhosts = useBoardWithGhosts(me.board);
  const oppHasTaunt = opp.board.some((m) => m.keywords.includes("Taunt"));
  const canAttackEnemyHero = myTurn && !!attacker && !oppHasTaunt;
  const boardFull = me.board.length >= 6;

  const logRef = useRef(null);
  useEffect(() => {
    if (logRef.current) logRef.current.scrollTop = logRef.current.scrollHeight;
  }, [state.log]);

  function handleCardClick(handIdx) {
    if (!myTurn) return;
    const cardId = me.hand[handIdx];
    const c = findCard(cardId);
    if (handCardBlocked(me, c)) { flash(tr("Both hands are holding items — use one first.")); return; }
    if (handCardCost(me, c) > me.mana) return;
    if (c.type === "minion" && boardFull) { flash(tr("Board is full.")); return; }
    setConfirmingIdx(handIdx);
  }
  function confirmPlayCard(handIdx) {
    setConfirmingIdx(null);
    const cardId = me.hand[handIdx];
    const c = findCard(cardId);
    if (c.type === "spell" && !bothHandsCrippled(me)) { onAction({ type: "equip", handIdx, slot: freeHandIdx(me) }); return; }
    if (c.needsTarget) { setAttacker(null); setPending({ kind: "card", handIdx, needsTarget: c.needsTarget }); return; }
    onAction({ type: "playCard", handIdx });
  }
  function handlePower() {
    if (!myTurn || me.powerUsed || me.mana < HERO_POWERS[me.hero].cost) return;
    const nt = HERO_POWERS[me.hero].needsTarget;
    if (nt) { setAttacker(null); setPending({ kind: "power", needsTarget: nt }); return; }
    onAction({ type: "power" });
  }
  function handleMinionClick(m, isEnemy, ownerIdx) {
    if (pending) {
      // resolving a target
      if (pending.needsTarget === "enemyMinion" && isEnemy) resolveTarget({ type: "minion", uid: m.uid, playerIdx: ownerIdx });
      if (pending.needsTarget === "friendlyMinion" && !isEnemy) resolveTarget({ type: "minion", uid: m.uid, playerIdx: ownerIdx });
      if (pending.needsTarget === "any") resolveTarget({ type: "minion", uid: m.uid, playerIdx: ownerIdx });
      if (pending.needsTarget === "enemyAny" && isEnemy) resolveTarget({ type: "minion", uid: m.uid, playerIdx: ownerIdx });
      if (pending.needsTarget === "anyMinion") resolveTarget({ type: "minion", uid: m.uid, playerIdx: ownerIdx });
      return;
    }
    if (!myTurn) return;
    if (!isEnemy) {
      if (!m.canAttack) { flash(isFrozenNow(m) ? tr("{card} is frozen and can't attack.", { card: cardNameL(m) }) : tr("{card} can't play anymore this turn.", { card: cardNameL(m) })); return; }
      setAttacker(attacker === m.uid ? null : m.uid);
      return;
    }
    if (isEnemy) {
      if (!attacker) { flash(tr("Select one of your minions first, then choose a target.")); return; }
      if (oppHasTaunt && !m.keywords.includes("Taunt")) { flash(tr("A Taunt minion is guarding the enemy — attack it first.")); return; }
      onAction({ type: "attack", attackerUid: attacker, target: { type: "minion", uid: m.uid } });
      setAttacker(null);
    }
  }
  function handleHeroClick(isEnemy, playerIdx) {
    if (pending) {
      if (pending.needsTarget === "any") resolveTarget({ type: "hero", playerIdx });
      if (pending.needsTarget === "enemyAny" && isEnemy) resolveTarget({ type: "hero", playerIdx });
      return;
    }
    if (!myTurn) return;
    if (isEnemy) {
      if (!attacker) { flash(tr("Select one of your minions first, then choose a target.")); return; }
      if (oppHasTaunt) { flash(tr("A Taunt minion is guarding the enemy hero — attack it first.")); return; }
      onAction({ type: "attack", attackerUid: attacker, target: { type: "hero" } });
      setAttacker(null);
    }
  }
  function dragPower(chosen) {
    if (!myTurn || me.powerUsed || me.mana < HERO_POWERS[me.hero].cost || !chosen) return;
    setAttacker(null); setPending(null);
    onAction({ type: "power", chosen });
  }
  function dragAttack(m, target) {
    if (pending || !myTurn || !m) return;
    if (!m.canAttack) { flash(isFrozenNow(m) ? tr("{card} is frozen and can't attack.", { card: cardNameL(m) }) : tr("{card} can't play anymore this turn.", { card: cardNameL(m) })); return; }
    if (target.type === "hero") {
      if (oppHasTaunt) { flash(tr("A Taunt minion is guarding the enemy hero — attack it first.")); return; }
      onAction({ type: "attack", attackerUid: m.uid, target: { type: "hero" } });
    } else {
      if (oppHasTaunt && !target.m.keywords.includes("Taunt")) { flash(tr("A Taunt minion is guarding the enemy — attack it first.")); return; }
      onAction({ type: "attack", attackerUid: m.uid, target: { type: "minion", uid: target.m.uid } });
    }
    setAttacker(null);
  }
  // what the hands / aimed shot pieces need (see frag/i_hands.jsx)
  const handsApi = {
    state, me, opp, myIdx, myTurn, onAction, flash,
    useSlot(slot) {
      const h = handsView(me)[slot];
      if (!myTurn || !h || !h.item) return;
      const c = findCard(h.item);
      if (slotUseCost(me, c) > me.mana) { flash(tr("Not enough AP.")); return; }
      if (c.needsTarget) { setAttacker(null); setPending({ kind: "card", slot, needsTarget: c.needsTarget }); return; }
      onAction({ type: "playCard", slot });
    },
  };
  function resolveTarget(chosen) {
    if (pending.kind === "card") onAction(pending.slot === 0 || pending.slot === 1 ? { type: "playCard", slot: pending.slot, chosen } : { type: "playCard", handIdx: pending.handIdx, chosen });
    else onAction({ type: "power", chosen });
    setPending(null);
  }

  // Full Graphics and Pixel Art draw this same match with their own layout. Every value
  // and handler they need is handed over here, so the rules live in one place.
  if (isThemedMode(display.mode)) {
    return (
      <>
      <TutorialLayer state={state} onAction={onAction} />
      <HandCrippleBanner state={state} myIdx={myIdx} />
      <DeluxeGame g={{
        state, me, opp, myIdx, myTurn, pending, attacker, onAction, onConcede, onSync, onBackToMenu, isCpuMatch, actionError, notice, logRef,
        confirmingIdx, setConfirmingIdx, confirmConcede, setConfirmConcede,
        showMulligan, mulliganSelected, mulliganElapsed, MULLIGAN_MAX, toggleMulliganCard, confirmMulligan,
        discoverSelected, setDiscoverSelected, showIdleWarning, showOpponentIdleNote, turnElapsed,
        oppBoardWithGhosts, meBoardWithGhosts, canAttackEnemyHero, boardFull,
        handleCardClick, confirmPlayCard, handlePower, handleMinionClick, handleHeroClick, cancelPending, dragAttack, dragPower, handsApi,
      }} />
      </>
    );
  }

  return (
    <div style={{ fontFamily: FONT, padding: 12, maxWidth: 900, margin: "0 auto" }}>
      <TutorialLayer state={state} onAction={onAction} />
      <HandCrippleBanner state={state} myIdx={myIdx} />
      {state.winner !== null && (() => {
        const iWon = state.winner === myIdx;
        const losingHero = state.players[state.winner === 0 ? 1 : 0].hero;
        const gif = HERO_LOSE_GIF_OVERRIDES[losingHero];
        return (
          <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.55)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 200 }}>
            <div style={{ background: "#fff", border: "3px solid #000", borderRadius: 10, padding: 24, textAlign: "center", minWidth: 260, boxShadow: "3px 3px 0 rgba(0,0,0,0.3)" }}>
              <h1 style={{ fontSize: 34, margin: 0, letterSpacing: 2, fontFamily: FONT, color: iWon ? "#1a7a1a" : "#c0392b" }}>
                {iWon ? tr("YOU WIN") : tr("YOU LOST")}
              </h1>
              <div style={{ fontSize: 11, color: "#666", marginTop: 4 }}>{tr("{hero} falls in the wasteland.", { hero: heroL(losingHero) })}</div>
              {/* the win/lose clip is skipped in "Notepad Style without Arts" */}
              {display.mode !== "noart" && <div style={{ width: 200, height: 200, border: "2px solid #000", borderRadius: 6, background: "#f2f2f2", display: "flex", alignItems: "center", justifyContent: "center", margin: "16px auto 0", overflow: "hidden" }}>
                {gif ? (
                  gif.startsWith("data:video") ? (
                    <video src={gif} autoPlay loop muted playsInline style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                  ) : (
                    <img src={gif} alt={heroL(losingHero)} style={{ width: "100%", height: "100%", objectFit: "cover" }} />
                  )
                ) : (
                  <span style={{ fontSize: 11, color: "#999" }}>{heroL(losingHero)}</span>
                )}
              </div>}
              <button
                onClick={onBackToMenu}
                style={{ marginTop: 18, padding: "10px 20px", fontFamily: FONT, fontSize: 13, fontWeight: 700, border: "2px solid #000", background: "#000", color: "#fff", cursor: "pointer", borderRadius: 4 }}
              >
                {tr("Back to Menu")}</button>
            </div>
          </div>
        );
      })()}
      {pending && (
        <div style={{ textAlign: "center", marginBottom: 6, fontSize: 12 }}>
          {tr("Select a target…")}{" "}<button onClick={cancelPending} style={{ fontFamily: FONT, marginLeft: 8, cursor: "pointer" }}>{tr("cancel")}</button>
        </div>
      )}
      {notice && (
        <div style={{ textAlign: "center", marginBottom: 6, fontSize: 12, background: "#fff3f2", border: "1px solid #c0392b", color: "#8a1f14", padding: "4px 8px", borderRadius: 4 }}>
          {notice}
        </div>
      )}
      {actionError && (
        <div style={{ textAlign: "center", marginBottom: 6, fontSize: 12, background: "#fff3f2", border: "1px solid #c0392b", color: "#8a1f14", padding: "4px 8px", borderRadius: 4 }}>
          {tr(actionError)}
        </div>
      )}
      {showOpponentIdleNote && (
        <div style={{ textAlign: "center", marginBottom: 6, fontSize: 11, color: "#c0392b" }}>
          {tr("Opponent has been idle a while — waiting for them to respond or time out...")}</div>
      )}

      {/* opponent row */}
      <div style={{ position: "relative", marginBottom: 6, minHeight: 84 }}>
        <div style={{ position: "absolute", left: 270, bottom: 0, zIndex: 2 }}><AimButton api={handsApi} size={30} /></div>
        <HeroPanel api={handsApi} player={opp} isEnemy targetable={!!pending && (pending.needsTarget === "any" || pending.needsTarget === "enemyAny")} attackable={canAttackEnemyHero} onClick={() => handleHeroClick(true, myIdx === 0 ? 1 : 0)} bgColor={HERO_COLORS[opp.hero]} />
        <div style={{ position: "absolute", top: 0, left: 272, width: 112, maxHeight: 56, overflowY: "auto", display: "flex", flexWrap: "wrap", alignContent: "flex-start", gap: 3 }}>
          {Array.from({ length: opp.hand.length }).map((_, i) => (
            <div key={i} style={{ width: 18, height: 25, boxSizing: "border-box", border: "2px solid #000", borderRadius: 3, flexShrink: 0, background: "repeating-linear-gradient(45deg,#000,#000 2px,#fff 2px,#fff 4px)" }} />
          ))}
        </div>
      </div>
      <div data-tut-lane="opp" style={{ display: "flex", gap: 6, minHeight: 96, borderBottom: "1px dashed #999", paddingBottom: 8, marginBottom: 8, flexWrap: "wrap" }}>
        {oppBoardWithGhosts.map((m) =>
          m.__dying ? (
            <div key={m.uid} style={{ animation: "minionDisintegrate 1s forwards", pointerEvents: "none" }}>
              <BoardMinion m={m} isEnemy targetable={false} onClick={() => {}} />
            </div>
          ) : (
            <BoardMinion key={m.uid} m={m} isEnemy targetable={!!attacker || (pending && (pending.needsTarget === "enemyMinion" || pending.needsTarget === "any" || pending.needsTarget === "enemyAny" || pending.needsTarget === "anyMinion"))} onClick={() => handleMinionClick(m, true, myIdx === 0 ? 1 : 0)} />
          )
        )}
      </div>

      {/* board separator / log + concede */}
      <div style={{ display: "flex", gap: 8, alignItems: "stretch", marginBottom: 8 }}>
        <div ref={logRef} style={{ flex: 1, fontSize: 10, color: "#666", maxHeight: 46, overflowY: "auto", border: "1px solid #ccc", padding: 4, background: "#fafafa" }}>
          {(state.log || []).slice(-6).map((l, i) => {
            const text = typeof l === "string" ? l : l.text;
            const warn = typeof l === "string" ? false : l.warn;
            return <div key={i} style={warn ? { color: "#c0392b", fontWeight: 700 } : undefined}>{logL(text)}</div>;
          })}
        </div>
        <button onClick={onSync} title={tr("Force-refresh the game state")} style={{ fontFamily: FONT, padding: "6px 12px", border: "2px solid #000", background: "#fff", cursor: "pointer", borderRadius: 4, fontSize: 11 }}>{tr("Sync")}</button>
        <button onClick={() => setConfirmConcede(true)} style={{ fontFamily: FONT, padding: "6px 14px", border: "2px solid #000", background: "#fff", cursor: "pointer", borderRadius: 4, fontSize: 11 }}>{tr("Concede")}</button>
      </div>

      {/* my board (3-column grid of minions, up to 2 rows / 6 minions) + End Turn pinned right, under Concede */}
      <div style={{ display: "flex", gap: 8, alignItems: "flex-start", borderTop: "1px dashed #999", paddingTop: 8, marginBottom: 8 }}>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 70px)", gridAutoRows: 92, columnGap: 6, rowGap: 18, justifyContent: "start" }}>
          {meBoardWithGhosts.map((m) =>
            m.__dying ? (
              <div key={m.uid} style={{ animation: "minionDisintegrate 1s forwards", pointerEvents: "none" }}>
                <BoardMinion m={m} targetable={false} onClick={() => {}} />
              </div>
            ) : (
              <BoardMinion key={m.uid} m={m} selected={attacker === m.uid} targetable={pending && (pending.needsTarget === "friendlyMinion" || pending.needsTarget === "anyMinion")} onClick={() => handleMinionClick(m, false, myIdx)} />
            )
          )}
        </div>
        <button
          data-tut="endturn"
          onClick={() => { const o = tutEndTurnButton(tutS, myTurn); if (o && o.next) o.onClick(); else onAction({ type: "endTurn" }); }}
          disabled={(() => { const o = tutEndTurnButton(tutS, myTurn); return o ? o.disabled : !myTurn; })()}
          style={{
            marginLeft: "auto", flexShrink: 0, width: 70, height: 92, boxSizing: "border-box",
            fontFamily: FONT, border: "2px solid #000", borderRadius: 5,
            background: myTurn ? "#000" : "#ccc", cursor: myTurn ? "pointer" : "default",
            display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: 4,
          }}
        >
          <AutoScrollText text={(tutS.active && tutS.lessonDone ? tr("Next Lesson") : myTurn ? tr("End Turn") : tr("Wait For Opponent")).split(" ").join("\n")} height={44} fontSize={11} duration={6} bold color="#fff" />
          <div style={{ fontSize: 11, fontWeight: 700, marginTop: 3, color: myTurn ? (turnElapsed >= 60000 ? "#ff8a80" : "#fff") : "#999" }}>
            {myTurn && state.turnStartedAt
              ? (turnElapsed < 60000 ? `${Math.max(0, 60 - Math.floor(turnElapsed / 1000))}s` : `${Math.max(0, Math.ceil((120000 - turnElapsed) / 1000))}s`)
              : "—"}
          </div>
        </button>
      </div>

      {/* my hero row */}
      <div style={{ display: "flex", justifyContent: "flex-start", alignItems: "stretch", gap: 8, marginTop: 10, marginBottom: 8 }}>
        <HeroPanel api={handsApi} player={me} targetable={pending && pending.needsTarget === "any"} onClick={() => handleHeroClick(false, myIdx)} bgColor={HERO_COLORS[me.hero]} />
        <button
          data-tut="power"
          onClick={handlePower}
          disabled={!myTurn || me.powerUsed || me.mana < HERO_POWERS[me.hero].cost}
          style={{
            marginLeft: "auto", flexShrink: 0,
            fontFamily: FONT, padding: "8px 10px", border: "2px solid #000", borderRadius: 8,
            background: me.powerUsed ? "#ddd" : "#fff", cursor: myTurn ? "pointer" : "default",
            width: 130, height: 84, boxSizing: "border-box",
            display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center",
          }}
        >
          <AutoScrollText text={`${powerL(me.hero).name} (${HERO_POWERS[me.hero].cost})`} height={24} fontSize={11} duration={6} bold />
          <div style={{ marginTop: 4, width: "100%" }}>
            <AutoScrollText text={powerL(me.hero).desc} height={34} fontSize={9} duration={8} color="#444" />
          </div>
        </button>
      </div>

      {/* hand */}
      <div style={{ display: "flex", gap: 6, overflowX: "auto", paddingBottom: 6 }}>
        {me.hand.map((cardId, i) => {
          const c = findCard(cardId);
          const disabled = !myTurn || handCardCost(me, c) > me.mana || (c.type === "minion" && boardFull);
          return <span key={i} data-tut-card={c.name} style={{ display: "contents" }}><MiniCard cardId={cardId} onClick={() => handleCardClick(i)} disabled={disabled} allowDetail costText={itemCostLabel(me, c)} /></span>;
        })}
      </div>

      {/* play confirmation modal */}
      {confirmingIdx !== null && (
        <div data-tut-popup="1" style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.35)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 50 }} onClick={() => setConfirmingIdx(null)}>
          <div onClick={(e) => e.stopPropagation()} style={{ background: "#fff", border: "2px solid #000", borderRadius: 8, padding: 18, fontFamily: FONT, textAlign: "center", minWidth: 220 }}>
            <div data-kwtap="1" style={{ display: "flex", justifyContent: "center", marginBottom: 8 }}>
              <MiniCard cardId={me.hand[confirmingIdx]} disabled costText={me.hand[confirmingIdx] ? itemCostLabel(me, findCard(me.hand[confirmingIdx])) : null} />
            </div>
            {(() => {
              const cc = me.hand[confirmingIdx] && findCard(me.hand[confirmingIdx]);
              const equip = cc && cc.type === "spell" && !bothHandsCrippled(me);
              return equip ? (
                <div style={{ marginBottom: 12, fontSize: 13 }}>
                  <div style={{ fontWeight: 700 }}>{tr("Equip this item?")}</div>
                  <div style={{ fontSize: 11.5, color: "#555", marginTop: 4, maxWidth: 240 }}>{tr("1 AP to put it in your {hand}. Using it then costs {n} AP.", { hand: freeHandIdx(me) === 0 ? tr("left hand") : tr("right hand"), n: slotUseCost(me, cc) })}</div>
                </div>
              ) : <div style={{ marginBottom: 12, fontSize: 13 }}>{tr("Play this card?")}</div>;
            })()}
            <div style={{ display: "flex", gap: 10, justifyContent: "center" }}>
              <button data-tut="confirm-play" onClick={() => confirmPlayCard(confirmingIdx)} style={{ fontFamily: FONT, padding: "6px 16px", border: "2px solid #000", background: "#000", color: "#fff", cursor: "pointer", borderRadius: 4 }}>{tr("Yes")}</button>
              <button onClick={() => setConfirmingIdx(null)} style={{ fontFamily: FONT, padding: "6px 16px", border: "2px solid #000", background: "#fff", cursor: "pointer", borderRadius: 4 }}>{tr("No")}</button>
            </div>
          </div>
        </div>
      )}

      {/* concede confirmation modal */}
      {confirmConcede && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.35)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 50 }} onClick={() => setConfirmConcede(false)}>
          <div onClick={(e) => e.stopPropagation()} style={{ background: "#fff", border: "2px solid #000", borderRadius: 8, padding: 18, fontFamily: FONT, textAlign: "center", minWidth: 240 }}>
            <div style={{ marginBottom: 12, fontSize: 13 }}>{tr("Concede this game? You will lose.")}</div>
            <div style={{ display: "flex", gap: 10, justifyContent: "center" }}>
              <button onClick={() => { setConfirmConcede(false); onConcede(); }} style={{ fontFamily: FONT, padding: "6px 16px", border: "2px solid #000", background: "#000", color: "#fff", cursor: "pointer", borderRadius: 4 }}>{tr("Yes")}</button>
              <button onClick={() => setConfirmConcede(false)} style={{ fontFamily: FONT, padding: "6px 16px", border: "2px solid #000", background: "#fff", cursor: "pointer", borderRadius: 4 }}>{tr("No")}</button>
            </div>
          </div>
        </div>
      )}

      {/* AFK "are you still there?" modal — shown only to the idle active player */}
      {showIdleWarning && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.5)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 150 }}>
          <div style={{ background: "#fff", border: "3px solid #c0392b", borderRadius: 10, padding: 22, textAlign: "center", minWidth: 250 }}>
            <div style={{ fontWeight: 700, fontSize: 15 }}>{tr("Are you still there?")}</div>
            <div style={{ fontSize: 12, marginTop: 8, color: "#555" }}>
              {tr("Confirm within {n}s or you'll lose the game.", { n: Math.max(0, Math.ceil((120000 - turnElapsed) / 1000)) })}
            </div>
            <div style={{ fontSize: 11, marginTop: 6, color: "#999" }}>{tr("Confirming will end your current turn.")}</div>
            <button
              onClick={() => onAction({ type: "endTurn" })}
              style={{ marginTop: 16, padding: "9px 18px", fontFamily: FONT, fontWeight: 700, border: "2px solid #000", background: "#000", color: "#fff", cursor: "pointer", borderRadius: 4 }}
            >
              {tr("I'm here")}</button>
          </div>
        </div>
      )}

      {/* Mulligan modal — shown once, on this player's own first turn only */}
      {showMulligan && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.6)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 160 }}>
          <div style={{ background: "#fff", border: "3px solid #000", borderRadius: 10, padding: 20, textAlign: "center", maxWidth: 420 }}>
            <div style={{ fontWeight: 700, fontSize: 16 }}>{tr("Mulligan")}</div>
            <div style={{ fontSize: 12, marginTop: 6, color: "#555" }}>
              {tr("Pick up to {n} cards to shuffle back into your deck and redraw. Tap a card to select it.", { n: MULLIGAN_MAX })}
            </div>
            <div style={{ fontSize: 12, marginTop: 4, fontWeight: 700, color: "#c0392b" }}>
              {tr("{n}s to decide", { n: Math.max(0, Math.ceil((15000 - mulliganElapsed) / 1000)) })}
            </div>
            <div style={{ display: "flex", gap: 8, justifyContent: "center", flexWrap: "wrap", marginTop: 14 }}>
              {me.hand.map((cardId, i) => {
                const selected = mulliganSelected.includes(i);
                const capReached = !selected && mulliganSelected.length >= MULLIGAN_MAX;
                return (
                  <div key={i} onClick={() => toggleMulliganCard(i)} style={{ position: "relative", cursor: capReached ? "default" : "pointer", opacity: capReached ? 0.45 : 1 }}>
                    <MiniCard cardId={cardId} small />
                    {selected && (
                      <div style={{ position: "absolute", inset: 0, background: "rgba(192,57,43,0.35)", border: "3px solid #c0392b", borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center" }}>
                        <span style={{ fontSize: 22, fontWeight: 700, color: "#fff", textShadow: "0 0 3px #000" }}>↺</span>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
            <button
              onClick={confirmMulligan}
              style={{ marginTop: 16, padding: "9px 20px", fontFamily: FONT, fontWeight: 700, border: "2px solid #000", background: "#000", color: "#fff", cursor: "pointer", borderRadius: 4 }}
            >
              {tr("Confirm ({n} to shuffle)", { n: mulliganSelected.length })}
            </button>
          </div>
        </div>
      )}

      <PerkChoice state={state} myIdx={myIdx} onAction={onAction} />
      {/* Merchant / Discover modal — choose 1 of the offered cards */}
      {state.pendingDiscover && state.pendingDiscover.playerIdx === myIdx && !(state.pendingPerk && state.pendingPerk.playerIdx === myIdx) && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.6)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 170 }}>
          <div style={{ background: "#fff", border: "3px solid #000", borderRadius: 10, padding: 20, textAlign: "center", maxWidth: 420 }}>
            <div style={{ fontWeight: 700, fontSize: 16 }}>{state.pendingDiscover.title ? tr(state.pendingDiscover.title) : tr("Choose a Card")}</div>
            <div style={{ fontSize: 12, marginTop: 6, color: "#555" }}>{state.pendingDiscover.sub ? tr(state.pendingDiscover.sub) : tr("Pick one to add to your hand.")}</div>
            <div style={{ display: "flex", gap: 10, justifyContent: "center", flexWrap: "wrap", marginTop: 14 }}>
              {state.pendingDiscover.options.map((cardId, i) => {
                const selected = discoverSelected === cardId;
                return (
                  <div key={i} onClick={() => setDiscoverSelected(cardId)} style={{ cursor: "pointer", border: selected ? "3px solid #c0392b" : "3px solid transparent", borderRadius: 8, padding: 2 }}>
                    <MiniCard cardId={cardId} small />
                  </div>
                );
              })}
            </div>
            <button
              disabled={discoverSelected === null}
              onClick={() => onAction({ type: "discoverChoice", cardId: discoverSelected })}
              style={{ marginTop: 16, padding: "9px 20px", fontFamily: FONT, fontWeight: 700, border: "2px solid #000", background: discoverSelected !== null ? "#000" : "#ccc", color: "#fff", cursor: discoverSelected !== null ? "pointer" : "default", borderRadius: 4 }}
            >
              {tr("Confirm")}</button>
          </div>
        </div>
      )}
    </div>
  );
}

/* =========================================================================
   APP — orchestrates screens + matchmaking + polling
   ========================================================================= */
export default function App() {
  const [screen, setScreen] = useState("select"); // select | deckbuilder | searching | game | leaderboard | quests | shop | settings
  // Display Options (Settings screen) - remembered on this device, see DISPLAY SETTINGS above.
  const [displaySettings, setDisplaySettings] = useState(loadDisplaySettings);
  const displayValue = React.useMemo(() => ({
    ...displaySettings,
    setDisplay: (patch) => setDisplaySettings((prev) => { const next = { ...prev, ...patch }; saveDisplaySettings(next); return next; }),
  }), [displaySettings]);
  // Every tr() call below reads this, so it is set before anything renders.
  setCurrentLang(displaySettings.lang);
  useEffect(() => { try { document.documentElement.lang = displaySettings.lang || "en"; } catch (e) {} }, [displaySettings.lang]);
  const [hero, setHero] = useState(null);
  const [gameId, setGameId] = useState(null);
  const [myIdx, setMyIdx] = useState(null);
  const [gameState, setGameState] = useState(null);
  const [actionError, setActionError] = useState(null);
  const [screenNotice, setScreenNotice] = useState(null);
  const [customDecks, setCustomDecks] = useState({}); // hero -> array of 30 card ids
  const [deckBuilderHero, setDeckBuilderHero] = useState(null);
  const [isCpuMatch, setIsCpuMatch] = useState(false);
  const [user, setUser] = useState(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [myProfile, setMyProfile] = useState(null);
  SHOP.diamonds = (myProfile && myProfile.diamonds) || {};
  const myDiamondIds = Object.keys(SHOP.diamonds).filter((k) => SHOP.diamonds[k] > 0);
  const [profileLoading, setProfileLoading] = useState(true);
  const [myLegendaryRank, setMyLegendaryRank] = useState(null);
  const [onlineCount, setOnlineCount] = useState(null);
  const [reconnectInfo, setReconnectInfo] = useState(null); // {gameId, myIdx, hero} if an unfinished match was found
  const [profileSyncError, setProfileSyncError] = useState(false);
  const sessionId = user ? user.uid : null;
  const myFirstName = user && user.displayName ? user.displayName.split(" ")[0] : "";
  const matchListenerRef = useRef(null); // holds the current onSnapshot unsubscribe function
  const pollIntervalRef = useRef(null); // backup poll alongside the live match listener
  const lastFailedStateRef = useRef(null);
  const lastFailedProfileRef = useRef(null); // {uid, gameId} if a claimMatchReward call failed, so it can be retried
  const resultRecordedForRef = useRef(null); // gameId whose result we already recorded, so we never double-count

  // Retry a match-result claim that failed to go through (wins/losses/tier/
  // quests/bullets) — this is what actually protects progress; without it,
  // a failed call silently looked fine locally but the server never heard
  // about it. Safe to call repeatedly: claimMatchReward's own rewardsClaimed
  // guard means a retry after a successful-but-unconfirmed call just
  // returns the existing result instead of double-crediting.
  async function retryProfileSync() {
    if (!lastFailedProfileRef.current) return;
    const { gameId: failedGameId } = lastFailedProfileRef.current;
    try {
      const res = await callClaimMatchReward({ gameId: failedGameId });
      if (res.data && res.data.profile) setMyProfile(res.data.profile);
      lastFailedProfileRef.current = null;
      setProfileSyncError(false);
    } catch (e) {
      console.error("retryProfileSync failed:", e);
    }
  }

  // Background maintenance: retries a failed profile save, and every 10s
  // also nudges retry so progress isn't stuck relying on a manual click.
  useEffect(() => {
    if (!sessionId) return;
    const interval = setInterval(() => { retryProfileSync(); }, 10000);
    return () => clearInterval(interval);
  }, [sessionId]);

  // Guard against refreshing/closing the tab while a match result hasn't
  // actually been confirmed saved yet - this is what protects progress in
  // the exact scenario where someone refreshes before a retry gets to run.
  useEffect(() => {
    if (!profileSyncError) return;
    const handler = (e) => {
      e.preventDefault();
      e.returnValue = "Your last match result hasn't saved yet.";
      return e.returnValue;
    };
    window.addEventListener("beforeunload", handler);
    return () => window.removeEventListener("beforeunload", handler);
  }, [profileSyncError]);

  // "Online" presence: a lightweight heartbeat rather than a full realtime
  // presence system (which would need Firebase Realtime Database, a separate
  // product from Firestore). Every 30s we mark ourselves as seen and count
  // everyone seen in the last 60s. This reuses the existing users/{uid}
  // self-write rule as-is — no Firestore rules changes needed.
  const isAdminUser = !!(user && user.email && ADMIN_EMAILS.includes(user.email));
  useEffect(() => {
    if (!sessionId) return;
    let cancelled = false;
    async function heartbeat() {
      try { await setDoc(doc(db, "users", sessionId), { lastSeen: Date.now() }, { merge: true }); }
      catch (e) { console.error("Presence heartbeat failed:", e); }
    }
    async function countOnline() {
      try {
        // "online" = seen in the last 6 minutes (everyone checks in every 5)
        const res = await getCountFromServer(query(collection(db, "users"), where("lastSeen", ">", Date.now() - 360000)));
        if (!cancelled) setOnlineCount(res.data().count);
      } catch (e) {
        console.error("Online count failed:", e);
      }
    }
    heartbeat();
    const beat = setInterval(heartbeat, 300000);
    let count = null;
    if (isAdminUser) { setTimeout(countOnline, 1500); count = setInterval(countOnline, 60000); }
    else setOnlineCount(null);
    return () => { cancelled = true; clearInterval(beat); if (count) clearInterval(count); };
  }, [sessionId, isAdminUser]);

  useEffect(() => {
    if (myProfile?.tier !== "Legendary" || !sessionId) { setMyLegendaryRank(null); return; }
    (async () => {
      try {
        const snap = await getDocs(query(collection(db, "users"), where("tier", "==", "Legendary"), limit(500)));
        const list = snap.docs.map((d) => {
          const data = d.data();
          const { monthWins, monthLosses } = monthStatsFor(data);
          return { id: d.id, ratio: ratioFor(monthWins, monthLosses), monthWins };
        });
        list.sort((a, b) => b.ratio - a.ratio || b.monthWins - a.monthWins);
        const idx = list.findIndex((r) => r.id === sessionId);
        setMyLegendaryRank(idx === -1 ? null : idx + 1);
      } catch (e) {
        console.error("Legendary rank fetch failed:", e);
        setMyLegendaryRank(null);
      }
    })();
  }, [myProfile?.tier, sessionId]);

  useEffect(() => {
    const unsub = onAuthStateChanged(auth, (u) => { setUser(u); setAuthLoading(false); });
    return unsub;
  }, []);

  useEffect(() => () => { if (matchListenerRef.current) matchListenerRef.current(); if (pollIntervalRef.current) clearInterval(pollIntervalRef.current); }, []);

  // Check whether we're a participant in any unfinished match — this is what
  // lets someone who accidentally closed the tab or refreshed jump back in.
  // Unlike the artifact's local pointer, this queries Firestore directly, so
  // it's tied to the real, stable Google account rather than a per-tab id.
  // Only genuinely recent matches are offered — an old abandoned test match
  // sitting in the database with winner:null shouldn't haunt anyone forever,
  // and its stale turnStartedAt could otherwise trigger an instant AFK loss
  // the moment it's loaded.
  const RECONNECT_STALE_MS = 20 * 60 * 1000; // 20 minutes
  useEffect(() => {
    if (!user) { setReconnectInfo(null); return; }
    (async () => {
      try {
        const snap = await getDocs(query(collection(db, "matches"), where("playerIds", "array-contains", user.uid)));
        const now = Date.now();
        const unfinished = snap.docs
          .map((d) => ({ id: d.id, data: d.data() }))
          .filter(({ data }) => data.winner === null && data.turnStartedAt && (now - data.turnStartedAt) < RECONNECT_STALE_MS)
          .sort((a, b) => (b.data.turnStartedAt || 0) - (a.data.turnStartedAt || 0));
        if (unfinished.length > 0) {
          const match = unfinished[0];
          const myIdxInGame = match.data.players.findIndex((p) => p.sessionId === user.uid);
          if (myIdxInGame !== -1) {
            setReconnectInfo({ gameId: match.id, myIdx: myIdxInGame, hero: match.data.players[myIdxInGame].hero });
          }
        }
      } catch (e) {
        console.error("Reconnect check failed:", e);
      }
    })();
  }, [user]);

  async function reconnectToGame() {
    if (!reconnectInfo) return;
    const snap = await getDoc(doc(db, "matches", reconnectInfo.gameId));
    if (!snap.exists() || snap.data().winner !== null) { setReconnectInfo(null); return; }
    let state = snap.data();
    // Coming back counts as "still here" — if it's our turn, give a fresh
    // timer window instead of risking an immediate AFK loss on old data.
    if (state.turn === reconnectInfo.myIdx) {
      state = { ...state, turnStartedAt: Date.now(), version: (state.version || 1) + 1 };
      await fSet(["matches", reconnectInfo.gameId], state);
    }
    setGameId(reconnectInfo.gameId);
    setMyIdx(reconnectInfo.myIdx);
    setGameState(state);
    setIsCpuMatch(false);
    setScreen("game");
    setReconnectInfo(null);
    beginListening(reconnectInfo.gameId);
  }

  async function dismissReconnect() {
    if (reconnectInfo) {
      // Actually end the stale match server-side, so it's cleaned up for
      // good and doesn't keep lingering for the other player either.
      const snap = await getDoc(doc(db, "matches", reconnectInfo.gameId));
      if (snap.exists() && snap.data().winner === null) {
        const state = snap.data();
        state.winner = reconnectInfo.myIdx === 0 ? 1 : 0;
        state.version = (state.version || 1) + 1;
        await fSet(["matches", reconnectInfo.gameId], state);
      }
    }
    setReconnectInfo(null);
  }

  // Live profile listener instead of polling on a guessed schedule: this
  // pushes the correct data the moment it's actually available server-side,
  // whatever that timing turns out to be, rather than us trying to predict
  // how long a write takes to become visible to a fresh read. Firestore can
  // fire onSnapshot twice on first attach - once immediately from whatever's
  // in the local cache (possibly stale, from a previous session), then again
  // once the server confirms the real data. We ignore the cache-sourced one
  // entirely so the UI never shows that stale flash, and only commit once
  // the server has actually confirmed it.
  useEffect(() => {
    if (!sessionId) { setMyProfile(null); setProfileLoading(true); return; }
    setProfileLoading(true);
    let gotServerData = false;
    const offlineFallback = setTimeout(() => {
      if (!gotServerData) setProfileLoading(false); // don't loop forever if genuinely offline
    }, 5000);
    const unsub = onSnapshot(
      doc(db, "users", sessionId),
      (snap) => {
        if (snap.metadata.fromCache) return;
        gotServerData = true;
        clearTimeout(offlineFallback);
        setMyProfile(snap.exists() ? snap.data() : null);
        setProfileLoading(false);
      },
      (err) => { console.error("Profile listener failed:", err); clearTimeout(offlineFallback); setProfileLoading(false); }
    );
    return () => { unsub(); clearTimeout(offlineFallback); };
  }, [sessionId]);

  // All four of these now just ask a Cloud Function to do it (see
  // functions/index.js). The function re-checks ownership and the real
  // server-side Bullets balance itself before writing anything - the
  // client's local `myProfile` numbers are only used here for the
  // disabled-button / "can't afford it" UI, never trusted for the actual
  // deduction. On success we optimistically adopt the function's returned
  // profile so the UI updates instantly; the live onSnapshot listener will
  // also confirm the same data moments later regardless.
  async function chooseFirstHero(hero) {
    try {
      const res = await callClaimFirstHero({ hero });
      if (res.data) setMyProfile(res.data);
      TUT.set({ offer: true });
    } catch (e) {
      console.error("claimFirstHero failed:", e);
      setScreenNotice((e && e.message) || "Couldn't claim your first hero. Try again.");
    }
  }

  // Diamond packs / selling: errors are thrown back to the screen that asked
  async function buyDiamondPacks(count) {
    const res = await callBuyDiamondPacks({ count });
    if (res.data && res.data.profile) setMyProfile(res.data.profile);
    return res.data;
  }
  async function openDiamondPack() {
    const res = await callOpenDiamondPack();
    if (res.data && res.data.profile) setMyProfile(res.data.profile);
    return res.data;
  }
  async function sellCardForBullets(cardId, diamond) {
    const res = await callSellCard({ cardId, diamond: !!diamond });
    if (res.data && res.data.profile) setMyProfile(res.data.profile);
    return res.data;
  }
  async function sellDiamondDuplicates() {
    const res = await callSellDiamondDuplicates();
    if (res.data && res.data.profile) setMyProfile(res.data.profile);
    return res.data || {};
  }
  async function buyOneCard(card) {
    const res = await callBuyCardUnlock({ cardId: card.id });
    if (res.data) setMyProfile((prev) => ({ ...prev, ...res.data }));
    return res.data;
  }
  async function buyDiamondCard(card) {
    const res = await callBuyDiamondCard({ cardId: card.id });
    if (res.data && res.data.profile) setMyProfile(res.data.profile);
    return res.data;
  }
  SHOP.app = { buyDia: buyDiamondCard, buyPacks: buyDiamondPacks, openPack: openDiamondPack, sellCard: sellCardForBullets, sellDupes: sellDiamondDuplicates, buyCard: buyOneCard, go: (sc) => setScreen(sc), packsLeft: (myProfile && myProfile.packs && myProfile.packs.diamond) || 0 };

  async function buyUnlockAll() {
    if (!myProfile || (myProfile.bullets || 0) < UNLOCK_ALL_COST) return;
    if (!(await askConfirm(tr("Unlock everything for {n} Bullets?", { n: UNLOCK_ALL_COST })))) return;
    try {
      const res = await callBuyUnlockAll();
      if (res.data) setMyProfile((prev) => ({ ...prev, ...res.data }));
    } catch (e) {
      console.error("buyUnlockAll failed:", e);
      setScreenNotice((e && e.message) || "Purchase failed. Try again.");
    }
  }

  async function buyHeroUnlock(hero) {
    if (!myProfile || (myProfile.bullets || 0) < HERO_UNLOCK_COST || isHeroUnlocked(hero, myProfile)) return;
    if (!(await askConfirm(tr("Unlock {hero} for {n} Bullets?", { hero: heroL(hero), n: HERO_UNLOCK_COST })))) return;
    try {
      const res = await callBuyHeroUnlock({ hero });
      if (res.data) setMyProfile((prev) => ({ ...prev, ...res.data }));
    } catch (e) {
      console.error("buyHeroUnlock failed:", e);
      setScreenNotice((e && e.message) || "Purchase failed. Try again.");
    }
  }

  async function buyCardUnlock(card) {
    if (!myProfile) return;
    const cost = CARD_UNLOCK_COST[card.rarity] || 0;
    if ((myProfile.bullets || 0) < cost) return;
    if (isCardUnlocked(card, myProfile)) return;
    try {
      const res = await callBuyCardUnlock({ cardId: card.id });
      if (res.data) setMyProfile((prev) => ({ ...prev, ...res.data }));
    } catch (e) {
      console.error("buyCardUnlock failed:", e);
      setScreenNotice((e && e.message) || "Purchase failed. Try again.");
    }
  }

  // Record match results exactly once per match. This now hands the whole
  // thing to the claimMatchReward Cloud Function instead of computing
  // wins/tier/quests/bullets locally and writing them directly — the
  // function reads the match doc and the player's own server-side profile
  // itself and recomputes everything server-side, so nothing the client
  // claims about the outcome or the reward is trusted. Both players call
  // this independently for the same gameId; the function's own
  // rewardsClaimed guard (see functions/index.js) makes that safe, and also
  // makes retrying after a dropped connection safe (never double-credits).
  useEffect(() => {
    if (!gameState || gameState.winner === null || !user || isCpuMatch) return;
    if (resultRecordedForRef.current === gameId) return;
    resultRecordedForRef.current = gameId;
    (async () => {
      try {
        const res = await callClaimMatchReward({ gameId });
        if (res.data && res.data.profile) setMyProfile(res.data.profile);
        lastFailedProfileRef.current = null;
        setProfileSyncError(false);
      } catch (e) {
        console.error("claimMatchReward failed:", e);
        // Let the existing retry loop (retryProfileSync, every 10s) keep
        // trying — it just needs to know which match to retry, not a
        // locally-computed profile anymore.
        lastFailedProfileRef.current = { uid: user.uid, gameId };
        setProfileSyncError(true);
        resultRecordedForRef.current = null; // allow a retry to re-enter this effect
      }
    })();
  }, [gameState?.winner, gameId, user, isCpuMatch, myIdx]);

  useEffect(() => {
    if (!user) { setCustomDecks({}); return; }
    (async () => {
      const entries = await Promise.all(HEROES.map(async (h) => {
        const data = await fGet(["users", user.uid, "decks", h]);
        return [h, data ? data.deck : null];
      }));
      const loaded = {};
      entries.forEach(([h, deck]) => { if (validateDeck(deck, h)) loaded[h] = deck; });
      setCustomDecks(loaded);
    })();
  }, [user]);

  function openDeckBuilder(chosenHero) {
    setDeckBuilderHero(chosenHero);
    setScreen("deckbuilder");
  }

  async function saveCustomDeck(chosenHero, deckArray) {
    await fSet(["users", user.uid, "decks", chosenHero], { deck: deckArray });
    setCustomDecks((prev) => ({ ...prev, [chosenHero]: deckArray }));
    setScreen("select");
  }

  function startCpuMatch(chosenHero) {
    const myDeck = customDecks[chosenHero] || null;
    const cpuHero = HEROES[Math.floor(Math.random() * HEROES.length)];
    const newId = "cpu_" + uid();
    const state = initGame(newId, { sessionId, hero: chosenHero, deck: myDeck, displayName: myFirstName, diamonds: myDiamondIds }, { sessionId: "CPU", hero: cpuHero, deck: null, displayName: "CPU" });
    setGameId(newId);
    setMyIdx(0);
    setHero(chosenHero);
    setIsCpuMatch(true);
    setGameState(state);
    setScreen("game");
  }

  // ----- tutorial: a CPU match on prepared tables, one lesson after another -----
  function startTutorial(lessonIdx = 0) {
    const tHero = (myProfile && (myProfile.unlockedHeroes || [])[0]) || "Wanderer";
    TUT.set({ active: true, lesson: lessonIdx, step: 0, lessonDone: false, offer: false, hero: tHero, claimed: !!(myProfile && myProfile.tutorialRewardClaimed) });
    const state = tutBuildLesson(lessonIdx, tHero, myFirstName, sessionId);
    setGameId(state.gameId);
    setMyIdx(0);
    setHero(tHero);
    setIsCpuMatch(true);
    setGameState(state);
    setScreen("game");
  }
  function nextTutorialLesson() {
    const n = TUT.s.lesson + 1;
    if (n >= TUT_LESSONS.length) return;
    TUT.set({ lesson: n, step: 0, lessonDone: false });
    const state = tutBuildLesson(n, TUT.s.hero, myFirstName, sessionId);
    setGameId(state.gameId);
    setGameState(state);
  }
  async function claimTutorialReward() {
    const res = await callClaimTutorialReward();
    if (res.data) setMyProfile((prev) => ({ ...prev, ...res.data }));
    return res.data || {};
  }
  TUT.app = {
    start: startTutorial, next: nextTutorialLesson, claim: claimTutorialReward, exit: () => returnToMenu(),
    mutate: (fn) => setGameState((prev) => { if (!prev) return prev; const s2 = JSON.parse(JSON.stringify(prev)); fn(s2); s2.version = (prev.version || 1) + 1; return s2; }),
  };

  // Drive the CPU's turn: one action at a time, with a short pause between each for pacing.
  useEffect(() => {
    if (!isCpuMatch || !gameState || gameState.winner !== null) return;
    if (gameState.turn !== 1) return;
    if (gameState.tutorial) return; // the tutorial scripts the CPU itself
    const timer = setTimeout(() => {
      const action = aiDecideAction(gameState, 1);
      handleAction(action, 1);
    }, 700);
    return () => clearTimeout(timer);
  }, [isCpuMatch, gameState]);

  // Real-time listener on a live match document — replaces the old polling loop.
  function beginListening(matchId) {
    if (matchListenerRef.current) matchListenerRef.current();
    if (pollIntervalRef.current) clearInterval(pollIntervalRef.current);
    matchListenerRef.current = onSnapshot(doc(db, "matches", matchId), (snap) => {
      if (!snap.exists()) return;
      const g = snap.data();
      setGameState((prev) => (!prev || g.version >= prev.version ? g : prev));
    });
    // Backup catch-up: onSnapshot listeners can stall when a mobile tab is
    // backgrounded (switching apps) and don't always resume instantly. This
    // guarantees the client is never more than ~15s stale regardless, using
    // the same safe version-checked merge as the manual Sync button.
    const refresh = async () => {
      try {
        const snap = await getDoc(doc(db, "matches", matchId));
        if (snap.exists()) {
          const g = snap.data();
          setGameState((prev) => (!prev || g.version >= prev.version ? g : prev));
        }
      } catch (e) { console.error("Background match sync failed:", e); }
    };
    pollIntervalRef.current = setInterval(refresh, 15000);
    if (typeof document !== "undefined") {
      const onVisible = () => { if (document.visibilityState === "visible") refresh(); };
      document.addEventListener("visibilitychange", onVisible);
      matchListenerRef.current = (() => {
        const origUnsub = matchListenerRef.current;
        return () => { origUnsub(); document.removeEventListener("visibilitychange", onVisible); };
      })();
    }
  }

  // Atomically try to claim a waiting player's queue entry and turn it into a match.
  // Uses a Firestore transaction so two people can't both claim the same waiting
  // player at once.
  async function claimQueueEntry(targetUid, matchId, myInfo) {
    try {
      await runTransaction(db, async (tx) => {
        const ref = doc(db, "matchmakingQueue", targetUid);
        const snap = await tx.get(ref);
        if (!snap.exists() || snap.data().matchedInto) throw new Error("already taken");
        const theirInfo = snap.data();
        const state = initGame(matchId, { sessionId: theirInfo.uid, hero: theirInfo.hero, deck: theirInfo.deck, displayName: theirInfo.displayName, diamonds: theirInfo.diamonds || [] }, { sessionId: myInfo.uid, hero: myInfo.hero, deck: myInfo.deck, displayName: myInfo.displayName, diamonds: myInfo.diamonds || [] });
        tx.set(doc(db, "matches", matchId), { ...state, playerIds: [theirInfo.uid, myInfo.uid] });
        tx.update(ref, { matchedInto: matchId });
      });
      return true;
    } catch (e) {
      return false;
    }
  }

  // While waiting, listen on our own queue document for someone else to match with us.
  function listenForMatch(myUid) {
    if (matchListenerRef.current) matchListenerRef.current();
    matchListenerRef.current = onSnapshot(doc(db, "matchmakingQueue", myUid), async (snap) => {
      if (!snap.exists()) return;
      const data = snap.data();
      if (!data.matchedInto) return;
      if (matchListenerRef.current) { matchListenerRef.current(); matchListenerRef.current = null; }
      const matchSnap = await getDoc(doc(db, "matches", data.matchedInto));
      if (!matchSnap.exists()) { setScreen("select"); return; }
      const state = matchSnap.data();
      fDelete(["matchmakingQueue", myUid]);
      const legit = state.players.every((p) => validateDeck([...p.deck, ...p.hand], p.hero));
      if (!legit) {
        setScreenNotice("This match couldn't be verified (invalid deck detected) — please search again.");
        setTimeout(() => setScreenNotice(null), 6000);
        fDelete(["matches", data.matchedInto]);
        setScreen("select");
        return;
      }
      setGameId(data.matchedInto);
      setMyIdx(0);
      setGameState(state);
      setScreen("game");
      beginListening(data.matchedInto);
    });
  }

  async function startSearch(chosenHero) {
    setIsCpuMatch(false);
    setHero(chosenHero);
    setScreen("searching");
    const myDeck = customDecks[chosenHero] || null;
    const myUid = user.uid;

    // look for someone already waiting
    const qSnap = await getDocs(query(collection(db, "matchmakingQueue"), orderBy("createdAtMs"), limit(8)));
    const candidates = qSnap.docs
      .map((d) => d.data())
      .filter((d) => d.uid !== myUid && !d.matchedInto && Date.now() - (d.createdAtMs || 0) < 45000);

    for (const cand of candidates) {
      const matchId = uid();
      const claimed = await claimQueueEntry(cand.uid, matchId, { uid: myUid, hero: chosenHero, deck: myDeck, displayName: myFirstName, diamonds: myDiamondIds });
      if (claimed) {
        const matchSnap = await getDoc(doc(db, "matches", matchId));
        setGameId(matchId);
        setMyIdx(1);
        setGameState(matchSnap.data());
        setScreen("game");
        beginListening(matchId);
        return;
      }
    }

    // nobody available — become the waiting player
    await setDoc(doc(db, "matchmakingQueue", myUid), {
      uid: myUid, hero: chosenHero, deck: myDeck,
      displayName: myFirstName, diamonds: myDiamondIds,
      createdAtMs: Date.now(),
    });
    listenForMatch(myUid);
  }

  async function cancelSearch() {
    if (matchListenerRef.current) { matchListenerRef.current(); matchListenerRef.current = null; }
    if (user) await fDelete(["matchmakingQueue", user.uid]);
    setScreen("select");
  }

  async function pushState(newState) {
    newState.version = (gameState?.version || 1) + 1;
    setGameState(newState);
    if (isCpuMatch) return;
    const ok = await fSet(["matches", gameId], newState);
    if (!ok) {
      lastFailedStateRef.current = newState;
      setActionError("Your move didn't reach the opponent (connection issue). Tap Sync to retry.");
      setTimeout(() => setActionError(null), 6000);
    } else {
      lastFailedStateRef.current = null;
    }
  }

  async function manualSync() {
    if (!gameId || isCpuMatch) return;
    if (lastFailedStateRef.current) {
      const ok = await fSet(["matches", gameId], lastFailedStateRef.current);
      if (ok) { lastFailedStateRef.current = null; setActionError(null); return; }
      setActionError("Still couldn't reach the opponent. Check your connection and try again.");
      setTimeout(() => setActionError(null), 6000);
      return;
    }
    const snap = await getDoc(doc(db, "matches", gameId));
    if (snap.exists()) {
      const g = snap.data();
      setGameState((prev) => (!prev || g.version >= prev.version ? g : prev));
    }
  }

  function handleAction(action, actingIdx = myIdx) {
    if (!gameState || gameState.winner !== null) return;
    if (!tutAllowAction(action, gameState, actingIdx)) return; // the tutorial only lets the highlighted move through
    try {
      const state = JSON.parse(JSON.stringify(gameState));
      // while a perk choice is open for this player, nothing else can happen until it's picked
      if (state.pendingPerk && state.pendingPerk.playerIdx === actingIdx && ["playCard", "power", "attack", "endTurn", "equip", "aim"].includes(action.type)) return;
      const me = state.players[actingIdx];
      const enemyIdx = actingIdx === 0 ? 1 : 0;

      if (action.type === "playCard") {
        const fromSlot = action.slot === 0 || action.slot === 1;
        const slotHand = fromSlot ? handsOf(me)[action.slot] : null;
        if (fromSlot && (!slotHand.item || slotHand.hp <= 0)) return;
        const cardId = fromSlot ? slotHand.item : me.hand[action.handIdx];
        const c = findCard(cardId);
        if (!c) return;
        // items are equipped into a hand first - unless both hands are crippled
        if (!fromSlot && c.type === "spell" && !bothHandsCrippled(me)) return;
        const playCost = fromSlot ? slotUseCost(me, c) : handCardCost(me, c);
        if (playCost > me.mana) return;
        if (c.type === "minion" && me.board.length >= 6) return;
        if (fromSlot) slotHand.item = null;
        else me.hand.splice(action.handIdx, 1);
        me.mana -= playCost;
        if (!c.hero) me.matchStats.neutralCardsPlayed += 1;
        if (c.rarity === "epic") me.matchStats.epicCardsPlayed += 1;
        if (c.rarity === "unique") me.matchStats.uniqueCardsPlayed += 1;
        me.matchStats.cardPlays[c.name] = (me.matchStats.cardPlays[c.name] || 0) + 1;
        me.lastCardPlayed = cardId;
        let playedMinion = null;
        if (c.type === "minion") {
          playedMinion = makeMinionInstance(cardId, c.keywords.includes("Charge"));
          me.board.push(playedMinion);
        }
        log(state, `${me.hero} plays ${c.name}.`);
        const perkSkip = perkOnPlayCard(state, actingIdx, c, playedMinion); // Sabotage, Charismatic, No Country...
        if (c.effect && !perkSkip) {
          applyEffects(state, c.effect, actingIdx, actingIdx, action.chosen ? { uid: action.chosen.uid, type: action.chosen.type, playerIdx: action.chosen.playerIdx } : null, true, playedMinion);
        }
        removeDeadMinions(state);
        checkWin(state);
      } else if (action.type === "power") {
        const pw = HERO_POWERS[me.hero];
        if (me.powerUsed || me.mana < pw.cost) return;
        me.mana -= pw.cost;
        me.powerUsed = true;
        log(state, `${me.hero} uses ${pw.name}.`);
        if (me.hero === "Wanderer") drawCard(state, actingIdx);
        else if (me.hero === "Prepper") { me.armor += 2; me.matchStats.armorGained += 2; }
        else if (me.hero === "Bandit") dealDamageToPlayer(state, enemyIdx, 2);
        else if (me.hero === "Cyborg") { healPlayer(state, actingIdx, 1); me.matchStats.healthRestored += 1; me.armor += 1; me.matchStats.armorGained += 1; }
        else if (me.hero === "Mutant" && action.chosen) {
          const m = me.board.find((x) => x.uid === action.chosen.uid);
          if (m) { m.atk += 1; m.hp += 1; m.maxHp += 1; }
        } else if (me.hero === "Scientist" && action.chosen) {
          if (action.chosen.type === "hero") dealDamageToPlayer(state, action.chosen.playerIdx, 1);
          else {
            const owner = state.players[action.chosen.playerIdx];
            const m = owner.board.find((x) => x.uid === action.chosen.uid);
            if (m) damageMinion(state, m, 1, action.chosen.playerIdx);
          }
        }
        removeDeadMinions(state);
        checkWin(state);
      } else if (action.type === "attack") {
        const atk = me.board.find((x) => x.uid === action.attackerUid);
        if (!atk || !atk.canAttack) return;
        atk.canAttack = false;
        const enemy = state.players[enemyIdx];
        if (action.target.type === "hero") {
          dealDamageToPlayer(state, enemyIdx, atk.atk);
          log(state, `${atk.name} attacks ${enemy.hero} for ${atk.atk}.`);
          aimOnHeroHit(state, actingIdx, atk);
        } else {
          const def = enemy.board.find((x) => x.uid === action.target.uid);
          if (!def) return;
          log(state, `${atk.name} clashes with ${def.name}.`);
          const wasShielded = def.shielded;
          damageMinion(state, def, atk.atk, enemyIdx);
          if (atk.keywords.includes("Deathtouch") && !wasShielded) { destroyMinion(def); log(state, `${def.name} is destroyed instantly.`); }
          damageMinion(state, atk, def.atk, actingIdx);
          if (atk.keywords.includes("ToxicTouch") && !def.keywords.includes("Toxic")) { def.keywords.push("Toxic"); log(state, `${def.name} becomes Toxic.`); }
          if (def.keywords.includes("ToxicTouch") && !atk.keywords.includes("Toxic")) { atk.keywords.push("Toxic"); log(state, `${atk.name} becomes Toxic.`); }
        }
        const atkCardDef = atk.cardId ? findCard(atk.cardId) : null;
        if (atkCardDef && atkCardDef.onAttack) applyEffects(state, atkCardDef.onAttack, actingIdx, actingIdx, null);
        removeDeadMinions(state);
        checkWin(state);
      } else if (action.type === "endTurn") {
        me.board.forEach((m) => { if (m.frozenSkip) m.frozenSkip = false; }); // the missed turn is over - thaw
        perkOnTurnEnd(state, actingIdx);
        me.aim = null;
        state.turn = enemyIdx;
        startTurn(state);
      } else if (action.type === "afkTimeout") {
        // the player whose turn it currently is has been unresponsive past the hard limit
        const idleIdx = state.turn;
        if (state.winner === null) {
          state.winner = idleIdx === 0 ? 1 : 0;
          log(state, `${state.players[idleIdx].hero} was away too long. ${state.players[state.winner].hero} wins by default.`, true);
        }
      } else if (action.type === "mulligan") {
        if (!me.mulliganDone) {
          const cardIds = (action.cardIds || []).filter((id) => me.hand.includes(id)).slice(0, 2);
          cardIds.forEach((id) => {
            const idx = me.hand.indexOf(id);
            if (idx !== -1) { me.hand.splice(idx, 1); me.deck.push(id); }
          });
          me.deck = shuffle(me.deck);
          for (let i = 0; i < cardIds.length; i++) drawCard(state, actingIdx);
          me.mulliganDone = true;
          state.turnStartedAt = Date.now(); // fresh action-timer window starts after mulligan resolves
          log(state, cardIds.length > 0 ? `${me.hero} mulligans ${cardIds.length} card(s).` : `${me.hero} keeps their opening hand.`);
        }
      } else if (action.type === "equip" || action.type === "aim" || action.type === "aimCancel") {
        handsHandleAction(state, actingIdx, action);
      } else if (action.type === "choosePerk") {
        perkChoose(state, actingIdx, action.perkId);
      } else if (action.type === "discoverChoice") {
        if (state.pendingDiscover && state.pendingDiscover.playerIdx === actingIdx && state.pendingDiscover.options.includes(action.cardId) && perkResolveDiscover(state, actingIdx, action.cardId)) {
          // a perk card choice (Copycat, Freebie, Lucky Number 7, Sneaky Bastard) - done above
        } else if (state.pendingDiscover && state.pendingDiscover.playerIdx === actingIdx && state.pendingDiscover.options.includes(action.cardId)) {
          const chosenCard = findCard(action.cardId);
          addCardToHand(state, actingIdx, chosenCard.name);
          log(state, `${me.hero} chooses ${chosenCard.name}.`);
        }
        state.pendingDiscover = null;
        perkNextDiscover(state);
      }
      perkAfterAction(state);
      removeDeadMinions(state);
      checkWin(state);
      pushState(state);
    } catch (e) {
      console.error("Action failed:", e);
      setActionError("Something went wrong with that move — the game state was not changed. You can keep playing.");
      setTimeout(() => setActionError(null), 3500);
    }
  }

  async function concede() {
    tutEnd();
    const state = JSON.parse(JSON.stringify(gameState));
    state.winner = myIdx === 0 ? 1 : 0;
    log(state, `${state.players[myIdx].hero} concedes.`);
    await pushState(state);
    if (matchListenerRef.current) { matchListenerRef.current(); matchListenerRef.current = null; }
    if (pollIntervalRef.current) { clearInterval(pollIntervalRef.current); pollIntervalRef.current = null; }
    setScreen("select");
    setGameState(null);
    setGameId(null);
    setMyIdx(null);
    setHero(null);
    setIsCpuMatch(false);
  }

  // Leave a game that's already over (no concede/forfeit involved, just navigation).
  function returnToMenu() {
    tutEnd();
    if (matchListenerRef.current) { matchListenerRef.current(); matchListenerRef.current = null; }
    if (pollIntervalRef.current) { clearInterval(pollIntervalRef.current); pollIntervalRef.current = null; }
    setScreen("select");
    setGameState(null);
    setGameId(null);
    setMyIdx(null);
    setHero(null);
    setIsCpuMatch(false);
  }

  if (authLoading) {
    return (
      <DisplayContext.Provider value={displayValue}>
        {isThemedMode(displaySettings.mode) ? <FxBoot /> : <div style={{ fontFamily: FONT, padding: 20 }}>{tr("Loading...")}</div>}
      </DisplayContext.Provider>
    );
  }

  // Sign in / register (one Google button does both), with the skin and language pickers.
  if (!user) {
    return (
      <DisplayContext.Provider value={displayValue}>
        <LoginScreen onSignIn={signInWithGoogle} />
      </DisplayContext.Provider>
    );
  }

  const needsOnboarding = !profileLoading && (!myProfile || (!myProfile.unlockedAll && (!myProfile.unlockedHeroes || myProfile.unlockedHeroes.length === 0)));
  if (needsOnboarding && isThemedMode(displaySettings.mode)) {
    return (
      <DisplayContext.Provider value={displayValue}>
        <FxOnboarding onChoose={chooseFirstHero} notice={screenNotice ? tr(screenNotice) : null} />
      </DisplayContext.Provider>
    );
  }
  if (needsOnboarding) {
    return (
      <div style={{ fontFamily: FONT, padding: 20, textAlign: "center", maxWidth: 640, margin: "20px auto" }}>
        {screenNotice && <div style={{ fontSize: 12, color: "#8a1f14", marginBottom: 8 }}>{tr(screenNotice)}</div>}
        <h1 style={{ fontSize: 22, fontWeight: 700, borderBottom: "2px solid #000", paddingBottom: 10 }}>{tr("Choose Your First Hero")}</h1>
        <p style={{ fontSize: 13, color: "#333", marginTop: 10 }}>{tr("Pick one hero to unlock for free. This also unlocks every Standard Set common and rare neutral card, plus one random Standard Set neutral epic and one random Standard Set neutral unique - all free.")}</p>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill,minmax(140px,1fr))", gap: 10, marginTop: 16 }}>
          {HEROES.map((h) => (
            <button
              key={h}
              onClick={() => chooseFirstHero(h)}
              style={{ padding: 14, fontFamily: FONT, fontSize: 15, fontWeight: 700, border: "2px solid #000", background: HERO_COLORS[h], cursor: "pointer", borderRadius: 6 }}
            >
              {heroL(h)}
            </button>
          ))}
        </div>
      </div>
    );
  }

  return (
    <DisplayContext.Provider value={displayValue}>
    {isThemedMode(displaySettings.mode) ? (
      /* Full Graphics / Pixel Art: their own menus and table, fed with exactly the same state and callbacks */
      <FxApp a={{
        screen, setScreen, myFirstName, signOutUser, profileLoading, myProfile, onlineCount, screenNotice, profileSyncError, retryProfileSync,
        reconnectInfo, reconnectToGame, dismissReconnect, startSearch, openDeckBuilder, startCpuMatch, myLegendaryRank, customDecks, sessionId, user,
        buyUnlockAll, buyHeroUnlock, deckBuilderHero, saveCustomDeck, buyCardUnlock, hero, cancelSearch,
        gameState, myIdx, handleAction, concede, actionError, manualSync, returnToMenu, isCpuMatch,
      }} />
    ) : (
    <div style={{ minHeight: "100%", background: "#fff", color: "#111" }}>
      <style>{GLOBAL_STYLE}</style>
      {screen !== "game" && (
        <div style={{ maxWidth: 640, margin: "0 auto", padding: "8px 20px 0", display: "flex", justifyContent: "space-between", alignItems: "center", fontFamily: FONT, gap: 8 }}>
          {screen === "select" ? (
            <h1 style={{ margin: 0, flexShrink: 0, cursor: "pointer" }} title={tr("Main menu")} onClick={() => { if (screen !== "game") setScreen("select"); }}><BrandLogo variant="black" height={46} /></h1>
          ) : <span />}
          <div style={{ fontSize: 11, color: "#555", textAlign: "right", minWidth: 0 }}>
            <div>{myFirstName} — <button onClick={signOutUser} style={{ fontFamily: FONT, fontSize: 11, border: "none", background: "none", color: "#555", textDecoration: "underline", cursor: "pointer", marginLeft: 4 }}>{tr("Sign out")}</button></div>
            <div style={{
              display: "inline-block", marginTop: 3, padding: "2px 8px", borderRadius: 4, border: 0,
              background: TIER_STYLES.Gold.gradient, boxShadow: TIER_STYLES.Gold.glow, color: TIER_STYLES.Gold.text,
              fontWeight: 700, fontSize: 10,
            }}>
              {profileLoading ? "…" : tr("{n} Bullets", { n: myProfile?.bullets || 0 })}
            </div>
            <div>
              <button
                onClick={() => setScreen("shop")}
                style={{ marginTop: 3, padding: "2px 10px", fontFamily: FONT, fontWeight: 700, fontSize: 10, border: "2px solid #0a4fa0", background: "#1e78e0", color: "#fff", cursor: "pointer", borderRadius: 4 }}
              >
                {tr("Shop")}</button>
            </div>
            {onlineCount !== null && <div style={{ fontSize: 10, color: "#888", marginTop: 2 }}>{tr("Players Online:")}{" "}{onlineCount}</div>}
          </div>
        </div>
      )}
      {screenNotice && (
        <div style={{ maxWidth: 640, margin: "10px auto 0", fontFamily: FONT, fontSize: 12, background: "#fff3f2", border: "1px solid #c0392b", color: "#8a1f14", padding: "6px 10px", borderRadius: 4, textAlign: "center" }}>
          {tr(screenNotice)}
        </div>
      )}
      {profileSyncError && (
        <div style={{ maxWidth: 640, margin: "10px auto 0", fontFamily: FONT, fontSize: 12, background: "#fff3f2", border: "2px solid #c0392b", color: "#8a1f14", padding: "8px 10px", borderRadius: 4, textAlign: "center", fontWeight: 700 }}>
          {tr("Your last match result hasn't saved yet — please don't refresh or close the tab.")}<button onClick={retryProfileSync} style={{ fontFamily: FONT, fontWeight: 700, marginLeft: 8, padding: "2px 10px", border: "1px solid #8a1f14", background: "#c0392b", color: "#fff", cursor: "pointer", borderRadius: 3 }}>{tr("Retry now")}</button>
        </div>
      )}
      {screen === "select" && reconnectInfo && (
        <div style={{ maxWidth: 640, margin: "10px auto 0", fontFamily: FONT, fontSize: 12, background: "#eaf6ea", border: "1px solid #1a7a1a", color: "#0f4d0f", padding: "8px 10px", borderRadius: 4, textAlign: "center" }}>
          {tr("You have an unfinished game as {hero}.", { hero: heroL(reconnectInfo.hero) })}
          <button onClick={reconnectToGame} style={{ fontFamily: FONT, fontWeight: 700, marginLeft: 10, padding: "3px 10px", border: "1px solid #0f4d0f", background: "#1a7a1a", color: "#fff", cursor: "pointer", borderRadius: 3 }}>{tr("Reconnect")}</button>
          <button onClick={dismissReconnect} style={{ fontFamily: FONT, marginLeft: 6, padding: "3px 10px", border: "1px solid #999", background: "#fff", cursor: "pointer", borderRadius: 3 }}>{tr("Dismiss")}</button>
        </div>
      )}
      {screen === "select" && <HeroSelectScreen onPick={startSearch} onBuildDeck={openDeckBuilder} onPlayCpu={startCpuMatch} onShowLeaderboard={() => setScreen("leaderboard")} onShowQuests={() => setScreen("quests")} onShowShop={() => setScreen("shop")} onShowSettings={() => setScreen("settings")} myProfile={myProfile} myLegendaryRank={myLegendaryRank} customDecks={customDecks} />}
      {screen === "settings" && <SettingsScreen onBack={() => setScreen("select")} />}
      {screen === "select" && <TutorialOffer />}
      {["leaderboard", "quests", "shop"].includes(screen) && (
        <div style={{ maxWidth: 640, margin: "0 auto", padding: "12px 20px 0", fontFamily: FONT }}>
          <button onClick={() => setScreen("select")} style={{ padding: "6px 14px", fontFamily: FONT, fontSize: 12.5, fontWeight: 700, border: "2px solid #000", background: "#fff", cursor: "pointer", borderRadius: 4 }}>{tr("← Back")}</button>
        </div>
      )}
      {screen === "leaderboard" && <LeaderboardScreen onBack={() => setScreen("select")} myProfile={myProfile} sessionId={sessionId} profileLoading={profileLoading} />}
      {screen === "quests" && <QuestsScreen onBack={() => setScreen("select")} myProfile={myProfile} profileLoading={profileLoading} />}
      {screen === "shop" && <ShopScreen onBack={() => setScreen("select")} myProfile={myProfile} user={user} onBuyUnlockAll={buyUnlockAll} onBuyHero={buyHeroUnlock} />}
      {screen === "collection" && <CollectionScreen profile={myProfile} onBack={() => setScreen("select")} onPacks={() => setScreen("packs")} />}
      {screen === "packs" && <PacksScreen profile={myProfile} onBack={() => setScreen("select")} onShop={() => setScreen("shop")} />}
      <CardManageHost profile={myProfile} />
      {screen === "deckbuilder" && <DeckBuilderScreen hero={deckBuilderHero} initialDeck={customDecks[deckBuilderHero] || null} onSave={(deck) => saveCustomDeck(deckBuilderHero, deck)} onCancel={() => setScreen("select")} myProfile={myProfile} onBuyCard={buyCardUnlock} />}
      {screen === "searching" && <SearchingScreen hero={hero} onCancel={cancelSearch} />}
      {screen === "game" && gameState && <GameScreen key={gameState.tutKey || "game"} state={gameState} myIdx={myIdx} onAction={handleAction} onConcede={concede} actionError={actionError} onSync={manualSync} onBackToMenu={returnToMenu} isCpuMatch={isCpuMatch} />}
    </div>
    )}
    </DisplayContext.Provider>
  );
}
